// 使い分けを深める: near forms, contrast examples and pitfalls per grammar lesson (built by scripts/build-grammar-deep.py from scripts/grammar-deep/*.json; AI-written, not native-verified).
const GRAMMAR_DEEP={"1":{"lead":"タイ語には「は・が・を」のような助詞がないので、語の順番が意味を決めます。ここでは主語の省略、目的語を前に出す言い方、場所・時・程度の語の置き場所を扱います。","compare":[{"form":"หมากัดคน ／ คนกัดหมา","ro":"mǎa kàt khon ／ khon kàt mǎa","use":"助詞がないので、主語と目的語を入れ替えると意味が逆になる。「犬が人をかむ」／「人が犬をかむ」。","style":"標準"},{"form":"กินข้าว（主語なし）","ro":"kin khâao","use":"誰の話か分かれば主語を省く。答えでは目的語も省いて กินแล้ว「食べたよ」だけで言うことが多い。","style":"口語"},{"form":"อันนี้ผมไม่ชอบ（目的語 ＋ 主語 ＋ 動詞）","ro":"an níi phǒm mâi chɔ̂ɔp","use":"話題にしたい物を先に出す言い方。「これは好きじゃない」と、ほかと比べたり話題を切り替えたりするときに使う。","style":"口語"},{"form":"ผมกินข้าวที่บ้าน（… ＋ 場所）","ro":"phǒm kin khâao thîi bâan","use":"「家で」「とても」などは動詞と目的語の後ろに置く。時の語（พรุ่งนี้・เมื่อวาน）は文頭にも文末にも置ける。","style":"標準"}],"cases":[{"th":"น้องชอบหมามาก","ro":"nɔ́ɔng chɔ̂ɔp mǎa mâak","ja":"弟（妹）は犬が大好きです。","note":"「犬が好き」の「犬」も目的語として ชอบ の後ろ。มาก はさらにその後ろ。"},{"th":"พรุ่งนี้ผมไปทำงาน","ro":"phrûng níi phǒm pai tham ngaan","ja":"明日は仕事に行きます。","note":"時の語は文末（ผมไปทำงานพรุ่งนี้）でもよい。場所や程度の語ほど位置は厳しくない。"},{"th":"อันนี้ผมไม่ชอบ","ro":"an níi phǒm mâi chɔ̂ɔp","ja":"これは好きじゃないです。","note":"目的語を文頭に出すと「ほかのはともかく、これは」という対比の響きが出る。"},{"th":"ผมไปซื้อกาแฟ","ro":"phǒm pai sʉ́ʉ kaa fɛɛ","ja":"コーヒーを買いに行きます。","note":"動詞を続けるときは起こる順に並べる。日本語の「買いに行く」とは逆で「行く・買う」。"}],"pitfalls":["「〜が好き」「〜が欲しい」「〜が分かる」の「が」が付く名詞も、タイ語では目的語として動詞の後ろに置く：ผมชอบแมว「私は猫が好き」。","มาก「とても」は動詞の直後ではなく目的語の後ろ：ชอบหมามาก（○）／ ชอบมากหมา（×）。","主語を省いても、目上の人には文末の ครับ・ค่ะ は省かないほうが丁寧。省いてよいのは主語であって、丁寧さではない。"]},"2":{"lead":"迷いやすいのは、「とても」「わりと」「〜すぎる」など程度の語の位置と、「疲れた」「お腹すいた」の「た」の訳し方です。เป็น を入れてしまう誤りの見分け方も扱います。","compare":[{"form":"形容詞 ＋ มาก","ro":"mâak","use":"「とても」。いちばん中立で、説明にも質問にも使え、会話では มากๆ と重ねて強めることも多い。","style":"標準"},{"form":"形容詞 ＋ จัง","ro":"cang","use":"「ほんとに〜だなあ」と目の前の実感をこめた感嘆。เลย を足して ร้อนจังเลย のようにも言う。","style":"口語"},{"form":"ค่อนข้าง ＋ 形容詞","ro":"khɔ̂ɔn khâang","use":"「わりと・やや」。多くの程度の語と違い、形容詞の前に置く。","style":"標準"},{"form":"形容詞 ＋ เกินไป","ro":"kəən pai","use":"「〜すぎる」。不満や断りの理由によく使う：แพงเกินไป「高すぎる」。","style":"標準"}],"cases":[{"th":"ร้อนจังเลย","ro":"rɔ́ɔn cang ləəi","ja":"ほんと暑いね！","note":"ร้อนมาก は「とても暑い」と状態を伝える言い方。気持ちの強さは จัง のほうが出る。"},{"th":"ห้องนี้ค่อนข้างเล็ก","ro":"hɔ̂ɔng níi khɔ̂ɔn khâang lék","ja":"この部屋はわりと狭い。","note":"ค่อนข้าง は形容詞の前、มาก・จัง・เกินไป は後ろ、と位置で覚える。"},{"th":"อันนี้แพงเกินไป","ro":"an níi phɛɛng kəən pai","ja":"これは高すぎます。","note":"買い物で断るときの定番。"},{"th":"หิวแล้ว","ro":"hǐu lɛ́ɛo","ja":"お腹すいた。","note":"หิว だけでもよい。แล้ว を足すと「（今）すいてきた」という変化の感じが出る。"},{"th":"เขาเป็นหวัด","ro":"khǎo pen wàt","ja":"あの人は風邪をひいている。","note":"หวัด は形容詞ではないので เป็น が要る。ร้อน・ยุ่ง とは違う。"}],"pitfalls":["「病気だ」「心配だ」は日本語では形容詞のように感じるが、タイ語では เป็น が付く決まった形：เป็นหวัด「風邪をひいている」、เป็นห่วง「心配する」。","日本語の「疲れた」「お腹すいた」は過去ではなく今の状態。過去の語を探さず、เหนื่อย・หิว だけで言える。","「寒い」は อากาศหนาว、「冷たい」は น้ำเย็น。เย็น を天気に使うと「涼しい」になり、「暑い」「熱い」はどちらも ร้อน。","จัง は感嘆なので質問には使わない（ร้อนจังไหม は×）。質問は ร้อนไหม、程度を聞くなら ร้อนมากไหม。"]},"3":{"lead":"「説明は名詞の後ろ」は、「タイ料理」「喫茶店」のような名詞どうしの組み合わせにも当てはまります。数・類別詞・「この」が加わったときの順番と、「〜の」を ของ にしてしまう誤りを扱います。","compare":[{"form":"อาหารไทย（名詞 ＋ 名詞）","ro":"aa hǎan thai","use":"種類・用途を表す名詞も後ろに置く：ร้านกาแฟ「喫茶店」、น้ำส้ม「オレンジジュース」。","style":"標準"},{"form":"ร้านที่อร่อย（名詞 ＋ ที่ ＋ 形容詞）","ro":"ráan thîi à rɔ̀ɔi","use":"ほかと区別したいときや説明が長いときは ที่ を入れることが多い：ร้านที่อร่อยที่สุด「いちばんおいしい店」。","style":"標準"},{"form":"เสื้อสีแดงตัวนี้（名詞 ＋ 形容詞 ＋ 類別詞 ＋ นี้）","ro":"sʉ̂ʉa sǐi dɛɛng tuua níi","use":"全部そろうと「名詞→説明→（数と）類別詞→この・その」の順。นี้・นั้น はいちばん最後。","style":"標準"}],"cases":[{"th":"เสื้อสีแดงตัวนี้","ro":"sʉ̂ʉa sǐi dɛɛng tuua níi","ja":"この赤い服","note":"日本語と完全に逆の順。「この」に当たる นี้ は最後に来る。"},{"th":"แมวดำสองตัว","ro":"mɛɛo dam sɔ̌ɔng tuua","ja":"黒い猫2匹","note":"形容詞は名詞のすぐ後ろ、数と類別詞より前。"},{"th":"ร้านนี้อร่อย","ro":"ráan níi à rɔ̀ɔi","ja":"この店はおいしい。","note":"นี้ の後ろに形容詞が来ると文になる。ร้านอร่อย「おいしい店」は名詞のまとまり。"},{"th":"ขอดูตัวนั้นหน่อย","ro":"khɔ̌ɔ duu tuua nán nɔ̀ɔi","ja":"それ、見せてください。","note":"名詞が分かっていれば、類別詞＋นั้น だけで「それ」を指せる。"},{"th":"ผมมีเพื่อนคนไทย","ro":"phǒm mii phʉ̂ʉan khon thai","ja":"私にはタイ人の友達がいます。","note":"「タイ人の」は属性なので ของ を入れない。เพื่อนของคนไทย だと「タイ人の（持っている）友達」になる。"}],"pitfalls":["日本語の「〜の」を全部 ของ にしない。種類・属性（ภาษาไทย「タイ語」、เพื่อนคนไทย「タイ人の友達」）には付けず、ของ は持ち主を言うときに使う。","名詞どうしも後ろから説明する。「喫茶店」は ร้านกาแฟ（店＋コーヒー）で、日本語の順の กาแฟร้าน にはならない。","ทุก「すべての」・หลาย「いくつもの」・บาง「一部の」は数字と同じく類別詞の前に置く：นักเรียนทุกคน「生徒全員」。","色は สี を付けて เสื้อสีแดง と言うことが多い。สี を省くこともある。"]},"4":{"lead":"日本語の「〜は…です」は一つの形ですが、タイ語では中身によって เป็น・คือ・ชื่อ・อายุ・อยู่ に分かれ、形容詞なら何も入れません。否定も ไม่เป็น ではなく ไม่ใช่ です。","compare":[{"form":"เป็น ＋ 名詞","ro":"pen","use":"職業・国籍・関係など。「〜になる」の意味もあり、อยากเป็นหมอ は「医者になりたい」。","style":"標準"},{"form":"คือ ＋ 名詞・文","ro":"khʉʉ","use":"「〜とは…だ」「〜が…だ」と特定・定義する。後ろに文も置けるので「問題は〜ということだ」と言える。","style":"標準"},{"form":"ไม่ใช่ ＋ 名詞 ／ ไม่ได้เป็น ＋ 名詞","ro":"mâi châi ／ mâi dâai pen","use":"「〜ではない」。ไม่ใช่ が一般的で、ไม่ได้เป็น は「（思われているが）実は〜ではない」と打ち消す響きが出やすい。","style":"標準"},{"form":"คือ…（文頭）","ro":"khʉʉ","use":"「えっと・あのね・つまり」。言いにくいことを切り出したり、説明を始めたりするときのつなぎ。","style":"口語"}],"cases":[{"th":"นี่คืออะไร","ro":"nîi khʉʉ à rai","ja":"これは何ですか？","note":"正体をたずねる質問は คือ。会話では คือ を省いて นี่อะไร とも言う。"},{"th":"ปัญหาคือไม่มีเวลา","ro":"pan hǎa khʉʉ mâi mii wee laa","ja":"問題は時間がないことです。","note":"คือ の後ろには文を置ける。เป็น では言えない。"},{"th":"เขาไม่ใช่คนไทย","ro":"khǎo mâi châi khon thai","ja":"あの人はタイ人ではありません。","note":"名詞の否定は ไม่ใช่。ไม่เป็นคนไทย とは言わない。"},{"th":"ผมอายุสามสิบปี","ro":"phǒm aa yú sǎam sìp pii","ja":"私は30歳です。","note":"年齢は อายุ が述語で、เป็น は入れない。名前も ผมชื่อ… と ชื่อ が述語。"},{"th":"คือ วันนี้ไปไม่ได้","ro":"khʉʉ wan níi pai mâi dâai","ja":"えっと…今日は行けないんです。","note":"文頭の คือ は「です」ではなく、言いにくいことを切り出すつなぎ。"}],"pitfalls":["「です」に当たる語を毎回探さない。形容詞（ร้อน「暑い」）には何も入れず、場所は อยู่、名前は ชื่อ、年齢は อายุ。","ไม่เป็น は「（やり方を）知らない・できない」の意味になりやすい：ว่ายน้ำไม่เป็น「泳げない」。「先生ではない」は ไม่ใช่ครู か ไม่ได้เป็นครู。","自己紹介で ผมคือคนญี่ปุ่น と言うと、「（ほかでもなく）私が日本人です」と名乗り出るような響きになりやすい。属性なら ผมเป็นคนญี่ปุ่น。"]},"5":{"lead":"日本語の「いる（生き物）／ある（物）」の区別は、タイ語にはありません。ここでは มี と อยู่ を一文で使う形、「在宅・在席」の อยู่、家族や症状の言い方まで広げます。","compare":[{"form":"มี ＋ 名詞","ro":"mii","use":"「〜がいる・ある」。家族・予定・症状にも使う：มีพี่น้อง「兄弟がいる」、มีไข้「熱がある」。","style":"標準"},{"form":"名詞 ＋ อยู่ ＋ 場所","ro":"yùu","use":"既に分かっている人・物の居場所。「住んでいる」の意味もあり、ที่ は省くことが多い。","style":"標準"},{"form":"มี ＋ 名詞 ＋ อยู่ ＋ 場所","ro":"mii … yùu","use":"新しい物を紹介しながら、その場所も言う形。","style":"標準"},{"form":"人 ＋ อยู่ไหม ／ ไม่อยู่","ro":"yùu mǎi ／ mâi yùu","use":"場所を言わずに「（家・職場に）いる？」「留守だ」。電話や訪問でよく使う。","style":"標準"}],"cases":[{"th":"มีพี่น้องไหม","ro":"mii phîi nɔ́ɔng mǎi","ja":"兄弟はいますか？","note":"家族が「いる」は มี。日本語の「いる」につられて อยู่ にしない。"},{"th":"คุณแม่อยู่ไหม","ro":"khun mɛ̂ɛ yùu mǎi","ja":"お母さんはいますか？","note":"在宅かどうかを聞く อยู่。มีคุณแม่ไหม だと「お母さんはいるの？（存在するか）」になる。"},{"th":"มีแมวอยู่ใต้รถ","ro":"mii mɛɛo yùu tâi rót","ja":"車の下に猫がいる。","note":"初めて見つけた猫を紹介する形。うちの猫の居場所なら แมวอยู่ใต้รถ。"},{"th":"ผมอยู่กรุงเทพ","ro":"phǒm yùu krung thêep","ja":"私はバンコクに住んでいます。","note":"อยู่ は「住む」にもなる。"},{"th":"ตอนนี้ไม่อยู่","ro":"tɔɔn níi mâi yùu","ja":"今、留守にしています。／席を外しています。","note":"場所を言わない ไม่อยู่ は「不在」。ไม่มี は「（そもそも）いない・ない」。"}],"pitfalls":["生き物か物かで選ばない。「猫がいる」「本がある」はどちらも มี、「猫はどこ？」「本はどこ？」はどちらも อยู่ที่ไหน。","บน「上」・ใต้「下」・ใน「中」などの位置の語の前には、ふつう ที่ を付けない：อยู่บนโต๊ะ「机の上にある」。","อยู่ を動詞の後ろに置くと「〜している最中」の意味にもなる：ทำงานอยู่「仕事中だ」。居場所の อยู่ と混同しない。"]},"6":{"lead":"何でも ไม่ を付ければよいと思うと、「食べなかった」が「（ふだん）食べない」に聞こえたり、「行かなかった」と「行けない」を取り違えたりします。ここでは ไม่ได้ の二つの位置と、程度を加える ไม่ค่อย・ไม่…เลย を扱います。","compare":[{"form":"ไม่ ＋ 動詞・形容詞","ro":"mâi","use":"習慣・意志・状態の否定：ไม่กินเผ็ด「辛いものは食べない（ふだん）」、ไม่ไป「行かない（つもり）」。","style":"標準"},{"form":"ไม่ได้ ＋ 動詞","ro":"mâi dâai","use":"「〜しなかった」と過去の出来事を否定する基本形。「〜しているわけではない」と相手の思い込みを打ち消すときにも使う。","style":"標準"},{"form":"動詞 ＋ ไม่ได้","ro":"mâi dâai","use":"動詞の後ろに置くと「〜できない」：ไปไม่ได้「行けない」。ไม่ได้ไป「行かなかった」とは位置だけで意味が変わる。","style":"標準"},{"form":"ไม่ค่อย ＋ 動詞・形容詞 ／ ไม่ … เลย","ro":"mâi khɔ̂ɔi ／ mâi … ləəi","use":"ไม่ค่อย は「あまり〜ない」と弱め、ไม่…เลย は「全然〜ない」と強める。","style":"標準"}],"cases":[{"th":"เมื่อวานไม่ได้ไป","ro":"mʉ̂ʉa waan mâi dâai pai","ja":"昨日は行かなかった。","note":"過去の出来事の否定は ไม่ได้ が基本。เมื่อวานไม่ไป も言うが、「（行かないと決めて）行かなかった」と意志の響きが出る。"},{"th":"ผมไม่ได้โกรธ","ro":"phǒm mâi dâai kròot","ja":"怒ってないよ。","note":"「（そう見えるかもしれないが）怒っているわけではない」と打ち消す響き。"},{"th":"ไม่ใช่ ผมไม่ได้สั่ง","ro":"mâi châi phǒm mâi dâai sàng","ja":"違います、私は注文していません。","note":"ไม่ใช่ で内容を否定し、ไม่ได้ で「していない」と事実を否定する。間違った料理が来たときに。"},{"th":"ไม่เผ็ดเลย","ro":"mâi phèt ləəi","ja":"全然辛くない。","note":"ไม่ と เลย で挟むと「全然」。"},{"th":"ไม่ค่อยหิว","ro":"mâi khɔ̂ɔi hǐu","ja":"あまりお腹すいてない。","note":"ไม่หิว「すいてない」よりやわらかい。誘いを軽く断るときにも便利。"}],"pitfalls":["「朝ご飯を食べなかった」は ไม่ได้กินข้าวเช้า。ไม่กินข้าวเช้า は「朝ご飯は（ふだん）食べない」と習慣に聞こえやすい。","「暑くない」は ไม่ร้อน。ไม่ใช่ を形容詞に付けるのは、「暑いんじゃなくて…」と言い直すときなど。","ไม่ mâi「〜ない」、ไหม mǎi（疑問）、ใหม่ mài「新しい」は声調で区別する。"]},"7":{"lead":"はい・いいえの質問は ไหม だけではありません。過去の出来事や事実の確認には หรือเปล่า、「もう〜した？」には หรือยัง が自然で、答え方もそれぞれ違います。","compare":[{"form":"文 ＋ ไหม","ro":"mǎi","use":"「〜する？」。これからのこと・今の状態・誘い・申し出に使う。","style":"標準"},{"form":"文 ＋ หรือเปล่า","ro":"rʉ̌ʉ plàao","use":"「〜なの？（かどうか）」。過去の出来事や事実の確認に使いやすく、「いいえ」は เปล่า でも答えられる。","style":"標準"},{"form":"文 ＋ หรือยัง","ro":"rʉ̌ʉ yang","use":"「もう〜した？」。答えは〜แล้ว「もうした」か ยัง「まだ」。","style":"標準"},{"form":"文 ＋ เหรอ","ro":"rə̌ə","use":"「〜なの？」「へえ、そうなの？」。聞いたことや見たことへの意外さ・確認。","style":"口語"}],"cases":[{"th":"ไปด้วยกันไหม","ro":"pai dûuai kan mǎi","ja":"一緒に行かない？","note":"日本語の誘いは「行かない？」と否定形だが、タイ語は肯定の文＋ไหม。ไม่ไปไหม とはしない。"},{"th":"เมื่อวานไปหรือเปล่า","ro":"mʉ̂ʉa waan pai rʉ̌ʉ plàao","ja":"昨日行ったの？","note":"過去の出来事は หรือเปล่า が自然なことが多い。答えは ไป／เปล่า（または ไม่ได้ไป）。"},{"th":"เขาเป็นคนไทยหรือเปล่า","ro":"khǎo pen khon thai rʉ̌ʉ plàao","ja":"あの人はタイ人なの？","note":"เป็น＋名詞の文には ไหม より หรือเปล่า を使うことが多い。"},{"th":"กินข้าวหรือยัง","ro":"kin khâao rʉ̌ʉ yang","ja":"ご飯、もう食べた？","note":"答えは กินแล้ว「食べた」／ยัง「まだ」。あいさつ代わりにもよく使う。"},{"th":"ไม่ไปเหรอ","ro":"mâi pai rə̌ə","ja":"行かないの？","note":"否定＋เหรอ は「行かないの？」と意外に思う気持ち。誘いにはならない。"}],"pitfalls":["หรือยัง の答えに ไม่ を使うと「（これからも）しない」と聞こえる。「まだ」は ยัง、「まだ食べていない」は ยังไม่ได้กิน。","ไหม は会話では高い声で発音されることが多く、くだけた書き言葉では มั้ย とも書く。","「もう〜した？」を ไหม で聞かない。เสร็จไหม ではなく เสร็จหรือยัง「もう終わった？」。"]},"8":{"lead":"疑問詞は答えの位置に置くのが基本ですが、เมื่อไหร่ や ทำไม は位置で意味や響きが変わります。類別詞と組んで「どれ」になる ไหน や、「誰も・何も」の意味になる使い方も扱います。","compare":[{"form":"（ที่）ไหน ／ 類別詞 ＋ ไหน","ro":"thîi nǎi ／ nǎi","use":"場所は ที่ไหน、ただし ไปไหน のように「行く・来る」の後ろでは ที่ を省くことが多い。類別詞の後ろでは「どの・どれ」：อันไหน、คนไหน。","style":"標準"},{"form":"เมื่อไหร่（文末 ／ 文頭）","ro":"mʉ̂ʉa rài","use":"文末なら過去にも未来にも使える。文頭に置くと未来のことで、「いつになったら」と待ちきれない響きになりやすい。","style":"標準"},{"form":"ทำไม（文頭 ／ 文末）","ro":"tham mai","use":"「なぜ」は文頭が基本。文末の ไปทำไม は「何のために行くの」と目的を聞いたり、「行っても意味ない」と疑ったりする。","style":"標準"},{"form":"疑問詞 ＋ ก็ได้ ／ ไม่ ＋ 疑問詞","ro":"kɔ̂ɔ dâai ／ mâi …","use":"疑問詞が「何でも・誰も」の意味になる：อะไรก็ได้「何でもいい」、ไม่มีใคร「誰もいない」。","style":"標準"}],"cases":[{"th":"มาเมื่อไหร่","ro":"maa mʉ̂ʉa rài","ja":"いつ来たの？／いつ来るの？","note":"文末の เมื่อไหร่ は過去にも未来にもなる。どちらかは場面で決まる。"},{"th":"เมื่อไหร่จะเสร็จ","ro":"mʉ̂ʉa rài cà sèt","ja":"いつ終わるの？","note":"文頭の เมื่อไหร่ は未来。「まだなの？」という待ちきれない気持ちが出やすい。"},{"th":"เอาอันไหน","ro":"ao an nǎi","ja":"どれにする？","note":"類別詞＋ไหน で「どれ」。ที่ไหน「どこ」とは別の働き。"},{"th":"ไปไหนมา","ro":"pai nǎi maa","ja":"どこに行ってたの？","note":"あいさつとしてもよく使う。細かく答えず ไปธุระมา「ちょっと用事で」でもよい。"},{"th":"ไม่มีใครรู้","ro":"mâi mii khrai rúu","ja":"誰も知らない。","note":"ไม่มี＋ใคร で「誰も〜ない」。疑問ではない。"}],"pitfalls":["ไม่ได้ไปไหน は「どこに行かなかったの？」ではなく「どこにも行っていない」。疑問詞が否定と組むと「何も・どこにも」になる。","「誰の」は ของใคร：นี่ของใคร「これ、誰の？」。ใคร を名詞の前に置かない。","文頭の ไหน は会話で「どれどれ・ほら」にもなる：ไหนดูซิ「どれ、見せて」。"]},"9":{"lead":"หรือ は「AかBか」のほか、平叙文の「または」、文頭の「もしかして」にもなります。確認の ใช่ไหม と、「〜じゃなかったっけ？」と意外さを表す ไม่ใช่เหรอ の違いも扱います。","compare":[{"form":"A ＋ หรือ ＋ B","ro":"rʉ̌ʉ","use":"疑問文なら「それとも」、平叙文なら「または」。会話では rə̌ə に近く発音されることが多い。","style":"標準"},{"form":"A ＋ หรือว่า ＋ B ／ หรือว่า ＋ 文","ro":"rʉ̌ʉ wâa","use":"選択の質問で「それとも」をはっきり言う。文頭に置くと「もしかして〜？」と推測を口にする言い方になる。","style":"口語"},{"form":"文 ＋ ใช่ไหม","ro":"châi mǎi","use":"「〜だよね？」と自分の予想が合っているかを確かめる。答えは ใช่／ไม่ใช่。","style":"標準"},{"form":"文 ＋ ไม่ใช่เหรอ","ro":"mâi châi rə̌ə","use":"「〜じゃなかったっけ？」。そう思っていたのに違いそうだ、という意外さや軽い反論。","style":"口語"}],"cases":[{"th":"จะกินที่นี่หรือว่าเอากลับบ้าน","ro":"cà kin thîi nîi rʉ̌ʉ wâa ao klàp bâan","ja":"ここで食べる？それとも持ち帰る？","note":"店でよく聞く選択の質問。答えは กินที่นี่ か กลับบ้าน だけでよい。"},{"th":"ไปวันเสาร์หรือวันอาทิตย์ก็ได้","ro":"pai wan sǎo rʉ̌ʉ wan aa thít kɔ̂ɔ dâai","ja":"行くのは土曜でも日曜でもいいよ。","note":"平叙文の หรือ は「または」。質問ではない。"},{"th":"เขาเป็นคนญี่ปุ่นใช่ไหม","ro":"khǎo pen khon yîi pùn châi mǎi","ja":"あの人、日本人だよね？","note":"日本人だと思っていて確かめる。何も知らないなら เป็นคนญี่ปุ่นหรือเปล่า。"},{"th":"วันนี้วันหยุดไม่ใช่เหรอ","ro":"wan níi wan yùt mâi châi rə̌ə","ja":"今日って休みじゃなかったっけ？","note":"休みだと思っていたのに相手が出勤しようとしている、などの意外さ。"},{"th":"หรือว่าเขาลืม","ro":"rʉ̌ʉ wâa khǎo lʉʉm","ja":"もしかして、あの人忘れてる？","note":"文頭の หรือว่า は選択ではなく推測。"}],"pitfalls":["ใช่ と答えられるのは ใช่ไหม の質問。ว่างไหม「空いてる？」に ใช่ と答えるのは不自然で、ว่าง と動詞で答える。","ไม่ใช่เหรอ の質問に ใช่ だけで答えると、どちらの意味かあいまいになりやすい。วันนี้หยุด のように中身で答えると確実。","選択の文の最後に ไหม を付けると、「お茶かコーヒー、いる？」と、いるかどうかの質問に近くなる。どちらかを選んでほしいなら ไหม は付けない。"]},"10":{"lead":"類別詞は数を言うときだけの語ではなく、「一つ」の言い方や、色・大きさで選び分けるときにも働きます。日本語の「匹」「着」「本」の区別をそのまま持ち込まないことも大切です。","compare":[{"form":"名詞 ＋ 類別詞 ＋ หนึ่ง","ro":"nʉ̀ng","use":"「〜を一つ」と軽く言う形で、注文によく使う。数をはっきり言うなら หนึ่งแก้ว のように前に置く。","style":"口語"},{"form":"名詞 ＋ 類別詞 ＋ 形容詞（เสื้อตัวสีแดง）","ro":"sʉ̂ʉa tuua sǐi dɛɛng","use":"同じ種類の物から一つを選ぶ言い方で、類別詞が「〜のほう」の働きをする：「赤いほうのシャツ」。","style":"口語"},{"form":"名詞が類別詞を兼ねる（ห้องสองห้อง）","ro":"hɔ̂ɔng sɔ̌ɔng hɔ̂ɔng","use":"ห้อง「部屋」・ร้าน「店」などは名詞がそのまま類別詞になり、数えるときは同じ語をくり返すことが多い。","style":"標準"},{"form":"อัน","ro":"an","use":"小物や形のはっきりしない物に使う万能の類別詞。正しい類別詞がわからなくても、店では อันนี้「これ」で通じることが多い。","style":"くだけた"}],"cases":[{"th":"ขอกาแฟแก้วหนึ่ง","ro":"khɔ̌ɔ kaa fɛɛ kɛ̂ɛo nʉ̀ng","ja":"コーヒーを1杯ください。","note":"หนึ่ง が類別詞の後ろ。「1杯」という数より「コーヒーを一つ」という軽い言い方。"},{"th":"เอาเสื้อตัวสีแดง","ro":"ao sʉ̂ʉa tuua sǐi dɛɛng","ja":"赤いほうのシャツにします。","note":"類別詞＋形容詞で「〜のほう」を選ぶ。数は出てこない。"},{"th":"บ้านนี้มีห้องนอนสามห้อง","ro":"bâan níi mii hɔ̂ɔng nɔɔn sǎam hɔ̂ɔng","ja":"この家には寝室が3部屋ある。","note":"ห้อง が名詞と類別詞の両方に出る。"},{"th":"ที่บ้านมีแมวสามตัว","ro":"thîi bâan mii mɛɛo sǎam tuua","ja":"家に猫が3匹いる。","note":"動物はふつう ตัว。日本語のように「匹」「頭」「羽」で分けない。"},{"th":"ซื้อเสื้อมาสองตัว","ro":"sʉ́ʉ sʉ̂ʉa maa sɔ̌ɔng tuua","ja":"シャツを2枚買ってきた。","note":"服も動物と同じ ตัว。「枚」につられて แผ่น（紙・板など平たい物）を使わない。"}],"pitfalls":["ตัว は動物のほか、服・机・いすなどにも使う。逆に日本語では同じ「本」でも、瓶は ขวด、ペンは ด้าม、木は ต้น と分かれる。","人を ตัว で数えると見下した言い方になる。人は คน で、อัน も人・動物には使わない。"]},"11":{"lead":"จะ は未来形ではなく「まだ実現していないこと」の印なので、「〜するつもりだった」と過去の話にも使えます。すぐ起こることには กำลังจะ・จะ…แล้ว、ぼんやりした予定には ว่าจะ、「ちょっと後で」には เดี๋ยว を使い分けます。","compare":[{"form":"กำลังจะ ＋ 動詞","ro":"kam lang cà","use":"「今まさに〜するところ」と動作の直前を言う。出かける直前の連絡などに。","style":"標準"},{"form":"จะ ＋ 動詞 ＋ แล้ว","ro":"cà … lɛ́ɛo","use":"「もうすぐ〜する」と変化が近いことを知らせる：จะถึงแล้ว「もうすぐ着く」。","style":"口語"},{"form":"ว่าจะ ＋ 動詞","ro":"wâa cà","use":"「〜しようと思っている」。まだ決めきっていない予定で、จะ だけより控えめ。","style":"口語"},{"form":"เดี๋ยว ＋ 動詞","ro":"dǐiao","use":"「ちょっとしたら〜する・あとで〜するね」。会話でとてもよく使い、จะ と一緒にも言える。","style":"くだけた"}],"cases":[{"th":"กำลังจะออกจากบ้าน","ro":"kam lang cà ɔ̀ɔk càak bâan","ja":"今、家を出るところ。","note":"จะออกจากบ้าน だけだと「出る予定」で、いつかははっきりしない。"},{"th":"จะถึงแล้วนะ","ro":"cà thʉ̌ng lɛ́ɛo ná","ja":"もうすぐ着くよ。","note":"ถึงแล้ว「着いた」との違いは前の จะ だけ。"},{"th":"ว่าจะไปญี่ปุ่นปีหน้า","ro":"wâa cà pai yîi pùn pii nâa","ja":"来年日本に行こうと思っている。","note":"まだ固まっていない予定。予約まで済んでいるなら จะไป がふつう。"},{"th":"เดี๋ยวโทรกลับนะ","ro":"dǐiao thoo klàp ná","ja":"あとでかけ直すね。","note":"会話の「あとで」は เดี๋ยว が自然。ทีหลัง よりすぐ後の感じ。"},{"th":"เมื่อวานจะไปแต่ฝนตก","ro":"mʉ̂ʉa waan cà pai tɛ̀ɛ fǒn tòk","ja":"昨日行くつもりだったけど雨が降った。","note":"จะ は時制ではないので、過去の話でも「〜するつもりだった」を表せる。"}],"pitfalls":["否定は จะไม่＋動詞「〜しない（つもり）」。ไม่จะ とは言わない。","「やっぱりやめた」は ไม่…แล้ว が多い：ไม่ไปแล้ว「やっぱり行かない」。จะไม่ไป は単に「行かない予定」。","店で聞かれる จะเอาอะไร「何にしますか」の จะ は意向を聞く言い方。答えは เอา…／ขอ… でよく、จะ は付けなくてよい。","จะ は予定だけでなく、ปกติจะ…「ふだんは〜する」のように習慣を述べる文にもよく使う。"]},"12":{"lead":"日本語の「〜ている」は進行・結果の状態・習慣まで一つの形で表しますが、กำลัง…อยู่ が表すのは、ほぼ「今その動作の途中」だけです。「結婚している」「知っている」「毎朝走っている」を進行の形にしないことが大事です。","compare":[{"form":"กำลัง ＋ 動詞","ro":"kam lang","use":"「ちょうど今〜しているところ」。過去の場面（あのとき〜していた）にも使える。","style":"標準"},{"form":"動詞 ＋ อยู่","ro":"yùu","use":"動作・状態が続いていること。会話では อยู่ だけで言うことが多く、ไฟเปิดอยู่「電気がついている」のように状態にも使える。","style":"口語"},{"form":"動詞 ＋ แล้ว","ro":"lɛ́ɛo","use":"日本語の「結果の〜ている」の多くはこちら：แต่งงานแล้ว「結婚している」、มาแล้ว「来ている」。","style":"標準"},{"form":"動詞だけ（วิ่งทุกเช้า）","ro":"wîng thúk cháao","use":"習慣や「知っている」のような状態は印を付けない：วิ่งทุกเช้า「毎朝走っている」、รู้「知っている」。","style":"標準"}],"cases":[{"th":"เขาแต่งงานแล้ว","ro":"khǎo tɛ̀ng ngaan lɛ́ɛo","ja":"あの人は結婚している。","note":"結果の状態なので แล้ว。กำลังแต่งงาน だと「今まさに結婚式の最中」になる。"},{"th":"รู้จักเขาไหม","ro":"rúu càk khǎo mǎi","ja":"あの人を知ってる？","note":"「知っている」は状態の動詞なので印は不要。กำลังรู้จัก とは言わない。"},{"th":"ผมวิ่งที่สวนทุกเช้า","ro":"phǒm wîng thîi sǔuan thúk cháao","ja":"毎朝公園で走っている。","note":"習慣は動詞だけ。กำลังวิ่ง は「今走っている途中」。"},{"th":"ตอนนั้นกำลังอาบน้ำอยู่","ro":"tɔɔn nán kam lang àap náam yùu","ja":"そのときはシャワーを浴びていた。","note":"กำลัง は過去の一場面にも使える。電話に出られなかった理由などでよく言う。"},{"th":"อากาศกำลังดี","ro":"aa kàat kam lang dii","ja":"ちょうどいい天気だ。","note":"กำลังดี は「ちょうどいい」という決まった言い方で、進行の意味ではない。"}],"pitfalls":["「今〜していない」は ไม่ได้＋動詞 が自然なことが多い：ไม่ได้ดูทีวี「テレビは見ていない」。กำลังไม่… とは言わない。","อยู่ が進行の印か「〜にいる」かは位置で判断する。ทำงานอยู่ は「仕事中」、ทำงานอยู่ที่บ้าน は「家で仕事をしている」。","日本語の「来ている」「着いている」は แล้ว で言う：เขามาแล้ว。มาอยู่ は「住みに来る・滞在しに来る」という別の意味になりやすい。"]},"13":{"lead":"日本語の「もう」は、タイ語では แล้ว・อีก・ไม่…แล้ว に分かれ、「もう一杯」は แล้ว ではなく อีก です。また แล้ว は「それから」という接続の語にもなるので、位置で働きを見分けます。","compare":[{"form":"動詞・形容詞 ＋ แล้ว","ro":"lɛ́ɛo","use":"「もう〜した・〜になった」。時刻・時期にも付く：สิบโมงแล้ว「もう10時だ」。","style":"標準"},{"form":"ไม่ ＋ 動詞 ＋ แล้ว","ro":"mâi … lɛ́ɛo","use":"「もう〜しない・もう〜ではない」。前はそうだったが今は違う、という変化。","style":"標準"},{"form":"อีก ＋ 数 ＋ 類別詞","ro":"ìik","use":"追加の「もう・あと」は อีก：อีกแก้วหนึ่ง「もう一杯」、อีกห้านาที「あと5分」。","style":"標準"},{"form":"…แล้วก็…","ro":"lɛ́ɛo kɔ̂ɔ","use":"「〜して、それから〜」と動作を順につなぐ。会話では แล้ว だけでもつなげる。","style":"口語"}],"cases":[{"th":"ไม่กินแล้ว อิ่มแล้ว","ro":"mâi kin lɛ́ɛo ìm lɛ́ɛo","ja":"もう食べない。お腹いっぱい。","note":"ไม่…แล้ว は「もう〜しない」。อิ่มแล้ว は「満腹になった」という変化。"},{"th":"ขออีกแก้วหนึ่ง","ro":"khɔ̌ɔ ìik kɛ̂ɛo nʉ̀ng","ja":"もう1杯ください。","note":"追加の「もう」は อีก。แล้ว では通じない。"},{"th":"ไม่เจ็บแล้ว","ro":"mâi cèp lɛ́ɛo","ja":"もう痛くない。","note":"前は痛かったが今は違う。ไม่เจ็บ だけだと「痛くない」という事実だけ。"},{"th":"อาบน้ำแล้วก็นอน","ro":"àap náam lɛ́ɛo kɔ̂ɔ nɔɔn","ja":"シャワーを浴びてから寝る。","note":"ここの แล้ว は完了ではなく「それから」。これからの予定の文にも使える。"},{"th":"ไปแล้วนะ","ro":"pai lɛ́ɛo ná","ja":"じゃあ行くね。","note":"「もう行った」のほか、その場を離れるときのあいさつにもなる。"}],"pitfalls":["「もう少し」も อีก：อีกนิด・อีกหน่อย。แล้ว が表すのは「すでに」の「もう」だけ。","文頭の แล้ว は「それで・で」：แล้วคุณล่ะ「で、あなたは？」。แล้วแต่「〜次第」も完了とは関係ない。","ไม่…อีกแล้ว は「二度と〜しない」と強くなる：ไม่ไปอีกแล้ว「もう二度と行かない」。"]},"14":{"lead":"ยังไม่ の後ろに ได้ を入れるかどうかで、ニュアンスが少し変わります。また「まだ〜している」の反対は「もう〜していない」（ไม่…แล้ว）です。","compare":[{"form":"ยัง ＋ 動詞・形容詞 ＋（อยู่）","ro":"yang … yùu","use":"「まだ〜している・まだ〜だ」。文末に อยู่ を添えることが多い。","style":"標準"},{"form":"ยังไม่ ＋ 動詞・形容詞","ro":"yang mâi","use":"「まだ〜ない」。状態や気持ちにも使える：ยังไม่หิว「まだお腹は空いていない」。","style":"標準"},{"form":"ยังไม่ได้ ＋ 動詞","ro":"yang mâi dâai","use":"「（するはずのことを）まだしていない」。動作が済んでいないことを言うときに多い。","style":"標準"},{"form":"ไม่ ＋ 動詞 ＋ แล้ว","ro":"mâi … lɛ́ɛo","use":"「もう〜していない」。ยัง…อยู่ の反対。","style":"標準"}],"cases":[{"th":"ยังไม่ได้ทำการบ้าน","ro":"yang mâi dâai tham kaan bâan","ja":"まだ宿題をしていない。","note":"ยังไม่ได้ で「するべきことがまだ済んでいない」。"},{"th":"ยังไม่หิว","ro":"yang mâi hǐu","ja":"まだお腹は空いていない。","note":"状態には ได้ を入れない。ยังไม่ได้หิว とはふつう言わない。"},{"th":"ฝนยังตกอยู่","ro":"fǒn yang tòk yùu","ja":"まだ雨が降っている。","note":"ยัง…อยู่ で「まだ続いている」。"},{"th":"ฝนไม่ตกแล้ว","ro":"fǒn mâi tòk lɛ́ɛo","ja":"もう雨は降っていない。","note":"ยัง…อยู่ の反対は ไม่…แล้ว。"},{"th":"ยังเลย ยังไม่ได้กิน","ro":"yang ləəi yang mâi dâai kin","ja":"まだなんだ。まだ食べてない。","note":"ยังเลย は「まだなんだよ」という会話の言い方。"}],"pitfalls":["ยัง の位置は主語の後ろ、動詞の前：เขายังไม่มา（○）／ ยังเขาไม่มา（×）。","ยังไง は「どう・どうやって」の口語で、「まだ」とは関係ない：ไปยังไง「どうやって行くの？」。","「まだ一度も〜したことがない」は ยังไม่เคย。ยังไม่ だけでは「（今回は）まだしていない」の意味になる。"]},"15":{"lead":"เคย は「〜したことがある」だけでなく、「以前は〜していた（今はしていない）」という昔の習慣にも使います。ไม่เคย は「決して〜しない」という強い否定にもなります。","compare":[{"form":"เคย ＋ 動詞","ro":"khəəi","use":"「〜したことがある」。เมื่อก่อน などと組むと「以前は〜していた」。","style":"標準"},{"form":"ไม่เคย ＋ 動詞","ro":"mâi khəəi","use":"「〜したことがない」。人の性質について「一度も〜しない」という強い否定にもなる。","style":"標準"},{"form":"ยังไม่เคย ＋ 動詞","ro":"yang mâi khəəi","use":"「まだ〜したことがない」。これからする可能性を残す言い方。","style":"標準"}],"cases":[{"th":"ยังไม่เคยไปญี่ปุ่น","ro":"yang mâi khəəi pai yîi pùn","ja":"まだ日本に行ったことがない。","note":"ยัง が付くと「これから行くかもしれない」含みが出る。ไม่เคยไป だけなら事実を言うだけ。"},{"th":"เมื่อก่อนเคยสูบบุหรี่","ro":"mʉ̂ʉa kɔ̀ɔn khəəi sùup bù rìi","ja":"以前はたばこを吸っていた。","note":"昔の習慣の เคย。「今はもう吸わない」という含みになる。"},{"th":"เขาไม่เคยมาสาย","ro":"khǎo mâi khəəi maa sǎai","ja":"あの人は遅刻したことがない。","note":"「決して遅れない人だ」という性質を言うことが多い。"},{"th":"เคยกินทุเรียนไหม เคยครับ","ro":"khəəi kin thú riian mǎi khəəi khráp","ja":"ドリアンを食べたことある？―あります。","note":"答えは เคย／ไม่เคย をくり返す。ใช่ では答えない。"},{"th":"เคยไปกี่ครั้ง","ro":"khəəi pai kìi khráng","ja":"何回行ったことがある？","note":"回数は กี่ครั้ง。答えは ไปมาสองครั้ง「2回行った」など。"}],"pitfalls":["回数は動詞句の後ろに置く：เคยไปสองครั้ง「2回行ったことがある」。文頭の ครั้งหนึ่ง は「かつて一度」という語りの言い方になる。","「〜したことがない」と「〜しなかった」を混同しない。昨日・今日の一回の出来事は ไม่ได้、人生の経験は ไม่เคย。","เคย の後ろには動詞が来る。「タイに行ったことがある」は เคยไปเมืองไทย のように動詞を入れ、เคยเมืองไทย とはしない。"]},"16":{"lead":"อยาก は気持ちを伝える語で、店での注文の決まった言い方ではありません。注文は เอา・ขอ、改まった場面は ต้องการ、人に何かしてほしいときは อยากให้ と使い分けます。","compare":[{"form":"อยาก ＋ 動詞","ro":"yàak","use":"「〜したい」。自分にも他人にも使い、日本語の「〜たがる」のような形の変化はない。","style":"標準"},{"form":"อยากให้ ＋ 人 ＋ 動詞","ro":"yàak hâi","use":"「（人に）〜してほしい」。相手への希望・やわらかいお願い。","style":"標準"},{"form":"เอา／ขอ ＋ 物","ro":"ao ／ khɔ̌ɔ","use":"店での注文・依頼。เอา は「これにする」、ขอ は「ください」でより丁寧。","style":"標準"},{"form":"ต้องการ ＋ 名詞・動詞","ro":"tɔ̂ɔng kaan","use":"「必要とする・望む」。窓口・文書・案内など改まった場面で使う。","style":"改まった表現"}],"cases":[{"th":"อยากให้คุณมาด้วย","ro":"yàak hâi khun maa dûuai","ja":"あなたにも来てほしい。","note":"自分が行きたいなら อยากไป、相手に来てほしいなら อยากให้。"},{"th":"เอาอันนี้ครับ","ro":"ao an níi khráp","ja":"これにします。","note":"店で選ぶときは เอา。อยากได้อันนี้ は「これが欲しいなあ」という気持ちの表明。"},{"th":"ต้องการความช่วยเหลือไหม","ro":"tɔ̂ɔng kaan khwaam chûuai lʉ̌ʉa mǎi","ja":"お手伝いが必要ですか。","note":"ต้องการ は改まった響き。店員や案内の言葉でよく聞く。"},{"th":"เขาอยากเป็นหมอ","ro":"khǎo yàak pen mɔ̌ɔ","ja":"あの人は医者になりたがっている。","note":"他人の希望も อยาก のまま。"},{"th":"ไม่อยากไป","ro":"mâi yàak pai","ja":"行きたくない。","note":"否定は ไม่อยาก。ストレートに響くので、断るときは ไม่สะดวก「都合が悪い」なども使う。"}],"pitfalls":["อยาก（yàak 低声）と ยาก（yâak 下降声）「難しい」は音が似ている。声調を区別して発音する。","持ち続ける物や人には อยากมี が多い：อยากมีแฟน「恋人が欲しい」、อยากมีบ้าน「家が欲しい」。","目上の人に อยากให้ だけで頼むと、要求に聞こえることがある。ช่วย…หน่อยได้ไหม の形のほうがやわらかい。"]},"17":{"lead":"日本語の「できる」は、タイ語では理由によって語が変わります。ได้ と เป็น のほかに、体力・量の限界は ไหว、読み取れるか・思いつくかは ออก、案内文では สามารถ を使います。","compare":[{"form":"動詞 ＋ ไหว","ro":"wǎi","use":"「（体力・気力的に）もちこたえられる」。否定の ไม่ไหว「疲れて・量が多くて無理」でよく使う。","style":"標準"},{"form":"動詞 ＋ ออก","ro":"ɔ̀ɔk","use":"「読み取れる・思いつける」。อ่านออก「（文字が）読める」、คิดไม่ออก「思いつかない」。","style":"標準"},{"form":"สามารถ ＋ 動詞 ＋ ได้","ro":"sǎa mâat … dâai","use":"「〜することができる」。案内・説明文・ニュースなどの改まった言い方。会話では สามารถ を省くことが多い。","style":"改まった表現"}],"cases":[{"th":"เดินไม่ไหวแล้ว","ro":"dəən mâi wǎi lɛ́ɛo","ja":"もう歩けない。","note":"疲れて限界なら ไหว。เดินไม่ได้ だと、けがなどで歩けない意味に聞こえやすい。"},{"th":"กินไม่ไหว","ro":"kin mâi wǎi","ja":"食べきれない。","note":"量の限界。กินไม่ได้ は辛すぎる・アレルギーなどで「食べられない」。"},{"th":"อ่านภาษาไทยไม่ออก","ro":"àan phaa sǎa thai mâi ɔ̀ɔk","ja":"タイ語が読めない。","note":"文字を読み取れるかどうかは ออก。"},{"th":"ที่นี่สูบบุหรี่ได้ไหม","ro":"thîi nîi sùup bù rìi dâai mǎi","ja":"ここでたばこを吸ってもいいですか。","note":"許可の ได้。เป็น は使えない。"},{"th":"สามารถจองออนไลน์ได้","ro":"sǎa mâat cɔɔng ɔɔn lai dâai","ja":"オンラインで予約できます。","note":"案内文の言い方。会話なら จองออนไลน์ได้ で十分。"}],"pitfalls":["目的語があるとき ได้ は最後に置く：พูดภาษาไทยได้。ได้พูดภาษาไทย は「タイ語を話す機会があった」という別の意味。","ไหวไหม は「（体調や量は）大丈夫？いける？」と相手を気づかう決まった問い。答えは ไหว／ไม่ไหว。","ช่วยหน่อยได้ไหม「ちょっと手伝ってもらえる？」の ได้ไหม は能力ではなく依頼。"]},"18":{"lead":"ต้องไม่ と ไม่ต้อง は語順が逆になるだけで、「〜してはいけない」と「〜しなくていい」に分かれます。また、会話の助言は ควร より น่าจะ や ดีกว่า のほうがやわらかいことが多く、ต้อง には「きっと〜だ」という推量の用法もあります。","compare":[{"form":"ต้องไม่ ＋ 動詞","ro":"tɔ̂ɔng mâi","use":"「〜してはいけない（しないことが必要）」。ไม่ต้อง「〜しなくていい」と語順が逆。","style":"標準"},{"form":"น่าจะ ＋ 動詞","ro":"nâa cà","use":"「〜したほうがいいんじゃない」。やわらかい助言。他人や出来事について言うと「たぶん〜だろう」の推量になることが多い。","style":"標準"},{"form":"動詞 ＋ ดีกว่า","ro":"dii kwàa","use":"「〜したほうがいい・〜しようかな」。比べて決めた自分の判断を言うときによく使う。","style":"口語"},{"form":"ต้อง … แน่","ro":"tɔ̂ɔng … nɛ̂ɛ","use":"「きっと〜に違いない」。ต้อง の推量の用法で、義務の意味はない。","style":"標準"}],"cases":[{"th":"ต้องไม่บอกใครนะ","ro":"tɔ̂ɔng mâi bɔ̀ɔk khrai ná","ja":"誰にも言っちゃだめだよ。","note":"「言わないことが必要」＝禁止に近い。日常では อย่าบอกใครนะ のほうが多い。"},{"th":"ไม่ต้องบอกใคร","ro":"mâi tɔ̂ɔng bɔ̀ɔk khrai","ja":"誰にも言わなくていい。","note":"ไม่ต้อง は「必要がない」。言ってもかまわない。"},{"th":"น่าจะไปหาหมอนะ","ro":"nâa cà pai hǎa mɔ̌ɔ ná","ja":"医者に行ったほうがいいんじゃない？","note":"ควรไปหาหมอ より押しつけが弱く、友人への助言に向く。"},{"th":"กลับบ้านดีกว่า","ro":"klàp bâan dii kwàa","ja":"家に帰ったほうがいいな。","note":"自分のことを決めるときの ดีกว่า。ควร を使うと堅く聞こえる。"},{"th":"ต้องอร่อยแน่เลย","ro":"tɔ̂ɔng à rɔ̀ɔi nɛ̂ɛ ləəi","ja":"きっとおいしいに違いない。","note":"ต้อง の推量の用法。義務の意味ではない。"}],"pitfalls":["差し出された物を断るときの ไม่ต้องครับ／ค่ะ は「結構です・いりません」という丁寧な断り。","目上の人に ควร で助言すると「〜すべきです」と教える調子になる。น่าจะ… や ลอง…ดูไหม の提案の形がやわらかい。","禁止の強さ：ห้าม は規則・掲示（ห้ามสูบบุหรี่「禁煙」）、อย่า は相手への直接の制止、ต้องไม่ は守るべきことの確認。"]},"19":{"lead":"「〜してください」を全部 ช่วย…หน่อย で言おうとすると、物をもらうときや改まった場面で不自然になります。物には ขอ、より丁寧に頼むなら ได้ไหม を足し、張り紙や案内では กรุณา を使います。","compare":[{"form":"ช่วย ＋ 動詞 ＋ (ให้) หน่อยได้ไหม","ro":"chûuai … (hâi) nɔ̀ɔi dâai mǎi","use":"「〜していただけますか」。質問の形にして相手に断る余地を残す、丁寧な依頼。目上や初対面の人に。","style":"丁寧"},{"form":"ขอ ＋ 名詞","ro":"khɔ̌ɔ","use":"「〜をください」。物がほしいときは ช่วย ではなく ขอ。","style":"標準"},{"form":"กรุณา ＋ 動詞","ro":"kà rú naa","use":"「〜してください・お〜ください」。張り紙、放送、書類などの改まった指示。友達との会話では堅すぎる。","style":"改まった表現"}],"cases":[{"th":"ขอน้ำแข็งหน่อยครับ","ro":"khɔ̌ɔ nám khɛ̌ng nɔ̀ɔi khráp","ja":"氷をください。","note":"物がほしいときは ขอ＋名詞。ช่วย は使わない。"},{"th":"ช่วยพูดอีกทีได้ไหมคะ","ro":"chûuai phûut ìik thii dâai mǎi khá","ja":"もう一度言っていただけますか。","note":"ได้ไหม を足して質問にすると、見知らぬ人や目上への依頼として丁寧になる。"},{"th":"กรุณาถอดรองเท้า","ro":"kà rú naa thɔ̀ɔt rɔɔng tháao","ja":"靴をお脱ぎください。","note":"寺や家の入口の張り紙の言い方。口頭なら ถอดรองเท้าด้วยนะครับ などが普通。"},{"th":"รอสักครู่นะคะ","ro":"rɔɔ sàk khrûu ná khá","ja":"少々お待ちください。","note":"店員や電話でよく聞く丁寧な決まり文句。友達同士なら รอแป๊บนึง のようにくだける。"}],"pitfalls":["日本語の「〜をください」につられて ช่วยน้ำ とは言わない。物を求めるときは ขอน้ำ。","หน่อย も ครับ・ค่ะ も付けない動詞だけの文は、命令のように強く聞こえやすい。依頼なら หน่อย か นะ を添える。","ช่วยด้วย だけだと「助けて！」という緊急の叫び。ช่วยปิดประตูด้วย のように動詞を入れれば、ふつうの依頼になる。"]},"20":{"lead":"ลอง…ดู と ก่อน を覚えても、日本語の「先に」「前に」「最初は」「とりあえず」はタイ語で別々の形になります。ก่อน は動詞の後ろか前かで意味が変わり、「最初は」には ตอนแรก を使います。","compare":[{"form":"動詞 ＋ ดู","ro":"… duu","use":"ลอง を省いても「〜してみる」になる。ชิมดู「味見してみる」、ใส่ดู「着てみる」。","style":"標準"},{"form":"ก่อน ＋ 動詞・名詞","ro":"kɔ̀ɔn …","use":"「〜する前に」「〜の前に」。ก่อนนอน「寝る前に」、ก่อนเที่ยง「昼前に」。","style":"標準"},{"form":"ตอนแรก","ro":"tɔɔn rɛ̂ɛk","use":"「最初は（あとで変わった）」。気持ちや状況の変化を言うときの「最初」。","style":"標準"},{"form":"動詞 ＋ ไว้ก่อน","ro":"… wái kɔ̀ɔn","use":"「とりあえず〜しておく」。決めるのを後に回して、今はその状態にしておく。","style":"口語"}],"cases":[{"th":"ลองใส่ดูได้ไหมครับ","ro":"lɔɔng sài duu dâai mǎi khráp","ja":"試着してみてもいいですか。","note":"店で服や靴を試すときの決まった言い方。"},{"th":"ชิมดูสิ","ro":"chim duu sì","ja":"味見してみて。","note":"ลอง がなくても 動詞＋ดู で「〜してみる」になる。"},{"th":"ก่อนนอนต้องแปรงฟัน","ro":"kɔ̀ɔn nɔɔn tɔ̂ɔng prɛɛng fan","ja":"寝る前に歯を磨かないといけない。","note":"ก่อน が動詞の前に来ると「〜する前に」。"},{"th":"ตอนแรกไม่ชอบ แต่ตอนนี้ชอบแล้ว","ro":"tɔɔn rɛ̂ɛk mâi chɔ̂ɔp tɛ̀ɛ tɔɔn níi chɔ̂ɔp lɛ́ɛo","ja":"最初は好きじゃなかったけど、今は好きになった。","note":"「最初は」は ตอนแรก。ก่อน では言わない。"},{"th":"เก็บไว้ก่อน","ro":"kèp wái kɔ̀ɔn","ja":"とりあえず取っておこう。","note":"ไว้ก่อน は「決めるのは後で、ひとまず」。"}],"pitfalls":["ก่อน の位置で意味が変わる：กินก่อน「先に食べる」／ ก่อนกิน「食べる前に」。","「〜したことがある」という経験は ลอง…ดู ではなく เคย：เคยกินทุเรียนไหม「ドリアンを食べたことある？」。","เดี๋ยวก่อน は「ちょっと待って」という決まった表現で、「先に」の意味はない。"]},"21":{"lead":"กว่า と ที่สุด だけでは、「〜のほうが好き」「ずっと高い」「思ったほどではない」が言えません。動詞を比べるときは มากกว่า、差の大きさは กว่า の後ろ、「〜ほど…ない」には ไม่…เท่า を使います。","compare":[{"form":"形容詞 ＋ กว่า ＋ เยอะ・มาก","ro":"… kwàa yə́ / mâak","use":"「ずっと〜だ」。差の大きさは กว่า の後ろに置く。เยอะ は会話的。","style":"標準"},{"form":"動詞 ＋ 目的語 ＋ มากกว่า","ro":"… mâak kwàa","use":"「〜のほうが好き・よく〜する」。ชอบ のような動詞を比べるときは มากกว่า を使う。","style":"標準"},{"form":"ไม่ ＋ 形容詞 ＋ เท่า ／ 形容詞 ＋ เท่ากัน","ro":"mâi … thâo / … thâo kan","use":"ไม่…เท่า は「〜ほど…ない」、เท่ากัน は「同じくらい〜」。","style":"標準"},{"form":"形容詞 ＋ สุด ๆ","ro":"… sùt sùt","use":"「超〜・最高に〜」。会話やネットでよく使うくだけた強調。","style":"口語"}],"cases":[{"th":"ชอบกาแฟมากกว่าชา","ro":"chɔ̂ɔp kaa fɛɛ mâak kwàa chaa","ja":"お茶よりコーヒーのほうが好き。","note":"動詞 ชอบ を比べるので มากกว่า。ชอบกว่า とはふつう言わない。"},{"th":"อันนี้แพงกว่าเยอะ","ro":"an níi phɛɛng kwàa yə́","ja":"こっちのほうがずっと高い。","note":"差の大きさ เยอะ は กว่า の後ろ。"},{"th":"ไม่ไกลเท่าที่คิด","ro":"mâi klai thâo thîi khít","ja":"思ったほど遠くない。","note":"ไม่…เท่า で「〜ほどではない」。กว่า を使わずに比べる形。"},{"th":"สองคนนี้สูงเท่ากัน","ro":"sɔ̌ɔng khon níi sǔung thâo kan","ja":"この二人は背が同じくらいだ。","note":"等しいときは เท่ากัน。"},{"th":"อร่อยสุด ๆ","ro":"à rɔ̀ɔi sùt sùt","ja":"最高においしい！","note":"実際に一番かどうかより、気持ちの強さを表す。"}],"pitfalls":["「良くなった」という変化は ดีขึ้น。ดีกว่า は二つを比べるときだけ：อาการดีขึ้นแล้ว「症状は良くなった」。","「18歳以上」は 18 ปีขึ้นไป。มากกว่า 18 ปี は「18歳より上」で、18歳を含まないのがふつう。","強調の มาก は後ろに置く：ดีกว่ามาก（○）／ มากดีกว่า（×）。"]},"22":{"lead":"理由を言う形は เพราะ・ก็เลย のほかに、結論を導く เพราะฉะนั้น や案内文の เนื่องจาก…จึง があります。また、「〜してすみません」「〜してくれてありがとう」の理由は เพราะ ではなく ที่ でつなぎます。","compare":[{"form":"文 ＋ เพราะฉะนั้น ＋ 文","ro":"phrɔ́ chà nán","use":"「だから・したがって」。前の文全体を受けて結論を言う。説明や議論で多く、ก็เลย より論理を強く示す。","style":"標準"},{"form":"เนื่องจาก … จึง …","ro":"nʉ̂ʉang càak … cʉng …","use":"「〜のため、…」。案内・通知・報道・文章で使う改まった形。จึง は結果の前。","style":"改まった表現"},{"form":"ขอโทษ・ขอบคุณ ＋ ที่","ro":"khɔ̌ɔ thôot / khɔ̀ɔp khun thîi","use":"「〜してすみません」「〜してくれてありがとう」。謝る理由・お礼の理由は ที่ でつなぐ。","style":"標準"}],"cases":[{"th":"อร่อยเลยกินหมด","ro":"à rɔ̀ɔi ləəi kin mòt","ja":"おいしかったから全部食べた。","note":"会話では ก็ を省いて เลย だけでもよく言う。"},{"th":"พรุ่งนี้สอบ เพราะฉะนั้นคืนนี้ต้องอ่านหนังสือ","ro":"phrûng níi sɔ̀ɔp phrɔ́ chà nán khʉʉn níi tɔ̂ɔng àan nǎng sʉ̌ʉ","ja":"明日は試験だ。だから今夜は勉強しないといけない。","note":"เพราะฉะนั้น は文と文の間に置き、後ろに結論を続ける。"},{"th":"เนื่องจากฝนตกหนักจึงงดการแข่งขัน","ro":"nʉ̂ʉang càak fǒn tòk nàk cʉng ngót kaan khɛ̀ng khǎn","ja":"大雨のため、試合を中止します。","note":"お知らせの文体。会話ではあまり使わない。"},{"th":"ขอโทษที่มาสาย","ro":"khɔ̌ɔ thôot thîi maa sǎai","ja":"遅れてすみません。","note":"謝る理由は ที่。ขอโทษเพราะมาสาย は不自然。"},{"th":"ไม่อร่อยเลย","ro":"mâi à rɔ̀ɔi ləəi","ja":"全然おいしくない。","note":"否定と一緒の文末の เลย は「全然」で、理由・結果の意味ではない。"}],"pitfalls":["เพราะ は理由の前、เลย・จึง は結果の前に置く。日本語の「〜から」につられて理由の後ろに เพราะ を置かない。","เลย には「全然（否定と一緒）」「すぐ・そのまま」（กินเลย「どうぞ食べて」）の意味もある。位置と否定の有無で区別する。","เนื่องจาก・จึง は書き言葉の硬さがある。目上との会話でも เพราะ に ครับ・ค่ะ を付ければ十分丁寧。"]},"23":{"lead":"日本語の「〜たら」は条件にも時にも使えるため、何でも ถ้า で言うと「そうならないかもしれない」という含みが出ます。確実に起こることには พอ、「念のため」には เผื่อ、文章では หาก を使い分けます。","compare":[{"form":"พอ … ก็ …","ro":"phɔɔ … kɔ̂ɔ …","use":"「〜したら・〜するとすぐ」。起こるとわかっていることの後に何をするか。時を表す「たら」。","style":"標準"},{"form":"เผื่อ ＋ 文","ro":"phʉ̀ʉa","use":"「〜するといけないから・念のため」。備えの理由を言う。","style":"標準"},{"form":"หาก ／ ถ้าหาก","ro":"hàak / thâa hàak","use":"「〜の場合は」。案内・規則・文章で使う改まった条件。","style":"改まった表現"},{"form":"ไม่งั้น","ro":"mâi ngán","use":"「そうしないと・でないと」。条件を裏返して警告する。改まると ไม่อย่างนั้น。","style":"口語"}],"cases":[{"th":"พอถึงแล้วจะโทรหานะ","ro":"phɔɔ thʉ̌ng lɛ́ɛo cà thoo hǎa ná","ja":"着いたら電話するね。","note":"着くのは確実なので พอ。ถ้าถึง だと着かない可能性を含むように聞こえやすい。"},{"th":"เอาร่มไปเผื่อฝนตก","ro":"ao rôm pai phʉ̀ʉa fǒn tòk","ja":"雨が降るといけないから傘を持っていく。","note":"เผื่อ は備えの理由。ถ้า では言わない。"},{"th":"หากมีข้อสงสัยกรุณาติดต่อเจ้าหน้าที่","ro":"hàak mii khɔ̂ɔ sǒng sǎi kà rú naa tìt tɔ̀ɔ câo nâa thîi","ja":"ご不明な点がありましたら、係員までお問い合わせください。","note":"案内文の หาก。会話なら ถ้าสงสัยก็ถามได้ のように言う。"},{"th":"รีบไปเถอะ ไม่งั้นจะสาย","ro":"rîip pai thə̀ mâi ngán cà sǎai","ja":"急ごう、でないと遅れる。","note":"ไม่งั้น で「そうしないと」という裏返しの条件。"},{"th":"ถ้าผมเป็นคุณ ผมจะไม่ซื้อ","ro":"thâa phǒm pen khun phǒm cà mâi sʉ́ʉ","ja":"私があなただったら買わない。","note":"事実と反する仮定も ถ้า。動詞の形は変わらない。"}],"pitfalls":["結果の文に主語があるとき、ก็ は主語の後ろ：ถ้าฝนตก ผมก็ไม่ไป（○）／ ก็ผมไม่ไป（×）。","ถ้า の節は後ろにも置ける：ไปด้วยกันไหม ถ้าว่าง「暇なら一緒に行かない？」。会話で後から条件を足すときに多い。","タイ語には「〜ば・〜たら」の活用がないので、仮定か現実かは ถ้า・พอ と文脈で示す。"]},"24":{"lead":"ที่ で名詞を説明できるようになると、今度は何にでも ที่ を付けたり、日本語の「の」を ที่ にしたりする間違いが出ます。形容詞は名詞に直接付けられること、職業などは ที่ のない複合語になること、文章では ซึ่ง も使われることを押さえます。","compare":[{"form":"名詞 ＋ 形容詞","ro":"—","use":"บ้านใหญ่「大きな家」のように、性質を言うだけなら ที่ は要らない。คนที่สวย は「（何人かの中で）きれいな方の人」と特定する感じになりやすい。","style":"標準"},{"form":"คน ＋ 動詞 ＋ 目的語","ro":"khon …","use":"คนขับรถ「運転手」のように、職業や役割は ที่ を入れない複合語。คนที่ขับรถ は「（その時）運転していた人」。","style":"標準"},{"form":"名詞 ＋ ซึ่ง ＋ 説明の文","ro":"sʉ̂ng","use":"ที่ の改まった言い方。文章や報道で、名詞に説明を付け足すときに多い。","style":"文語"}],"cases":[{"th":"ผู้หญิงที่ใส่เสื้อสีแดงคือใคร","ro":"phûu yǐng thîi sài sʉ̂ʉa sǐi dɛɛng khʉʉ khrai","ja":"赤い服を着ている女性は誰？","note":"何人かの中から一人を特定するので ที่ が必要。"},{"th":"คนขับรถใจดีมาก","ro":"khon khàp rót cai dii mâak","ja":"運転手さんはとても親切だ。","note":"คนขับรถ は職業名の複合語で、ที่ を入れない。"},{"th":"อันที่ซื้อเมื่อวานอยู่ไหน","ro":"an thîi sʉ́ʉ mʉ̂ʉa waan yùu nǎi","ja":"昨日買ったのはどこ？","note":"名詞の代わりに อัน＋ที่ で「〜したもの」。日本語の「〜の」に当たる。"},{"th":"ที่พูดเมื่อกี้หมายความว่าอะไร","ro":"thîi phûut mʉ̂ʉa kîi mǎai khwaam wâa à rai","ja":"さっき言ったのはどういう意味？","note":"名詞なしの ที่＋文 で「〜したこと」。会話でよく使う。"},{"th":"พี่ชายผมซึ่งทำงานอยู่ที่ญี่ปุ่นจะกลับมาเดือนหน้า","ro":"phîi chaai phǒm sʉ̂ng tham ngaan yùu thîi yîi pùn cà klàp maa dʉʉan nâa","ja":"日本で働いている兄が来月帰ってくる。","note":"兄について説明を補う ซึ่ง。改まった文に多い。"}],"pitfalls":["日本語の「私の本」の「の」は ที่ ではなく ของ：หนังสือของผม（○）／ หนังสือที่ผม（×）。","ที่ の後ろに数が来ると順番の意味になる：คนที่สอง「2番目の人」、วันที่ 5「5日」。説明の文をつなぐ ที่ と区別する。","類別詞を入れて特定することも多い：เสื้อตัวที่ชอบ「気に入っている（その）服」。"]},"25":{"lead":"คิดว่า と บอกว่า だけでは、「てっきり〜と思った」「〜らしいよ」「〜しようと思う」「〜という気がする」の違いが出せません。ว่า の前の動詞を替えるだけで、思い違い・うわさ・予定・感じ方を言い分けられます。","compare":[{"form":"นึกว่า","ro":"nʉ́k wâa","use":"「てっきり〜だと思った（実は違った）」。思い違いに気づいたときに使う。","style":"標準"},{"form":"รู้สึกว่า","ro":"rúu sʉ̀k wâa","use":"「〜な気がする・〜と感じる」。根拠のはっきりしない印象や体感。","style":"標準"},{"form":"เขาว่า ／ ได้ยินว่า","ro":"khǎo wâa / dâai yin wâa","use":"「〜らしい・〜だそうだ」。人から聞いたうわさ。เขาว่า の เขา は特定の人ではなく「世間の人」のことが多い。","style":"口語"},{"form":"ว่าจะ ＋ 動詞","ro":"wâa cà","use":"「〜しようと思っている」。自分のまだ決まりきっていない予定。","style":"口語"}],"cases":[{"th":"นึกว่าเป็นคนญี่ปุ่น","ro":"nʉ́k wâa pen khon yîi pùn","ja":"てっきり日本人かと思った。","note":"実は違ったという含み。คิดว่า では思い違いの意味が出ない。"},{"th":"เขาว่าร้านนี้อร่อย","ro":"khǎo wâa ráan níi à rɔ̀ɔi","ja":"この店、おいしいらしいよ。","note":"うわさとして伝える。話し手は自分で確かめていない。"},{"th":"ว่าจะไปเที่ยวเชียงใหม่","ro":"wâa cà pai thîiao chiiang mài","ja":"チェンマイに旅行しようと思っている。","note":"คิดว่าจะไป とも言えるが、予定を言うなら ว่าจะ が短く自然。"},{"th":"รู้สึกว่าวันนี้ร้อนกว่าเมื่อวาน","ro":"rúu sʉ̀k wâa wan níi rɔ́ɔn kwàa mʉ̂ʉa waan","ja":"今日は昨日より暑い気がする。","note":"体で感じた印象は รู้สึกว่า。"},{"th":"ภาษาไทยเรียกว่าอะไร","ro":"phaa sǎa thai rîiak wâa à rai","ja":"タイ語で何と言いますか。","note":"เรียกว่า「〜と呼ぶ」。単語を聞くときの便利な形。"}],"pitfalls":["บอกว่า は内容の伝達、บอกให้ は「〜するように言う」という指示。後ろが ว่า か ให้ かで意味が変わる。","名前を言うときも ว่า を使う：ร้านนี้ชื่อว่าอะไร「この店は何という名前？」。日本語の「〜という」に当たる。","ว่า は単独で動詞にもなる：ว่าไง「どう？・何だって？」。"]},"26":{"lead":"ให้ の位置を覚えても、日本語の「〜てほしい」「〜するように言う」「〜させておく」「〜しますように」がどれも ให้ を使うことに気づかないと言い表せません。ให้ の前に来る動詞で、願い・指示・放置・祈りを言い分けます。","compare":[{"form":"อยากให้ ＋ 人 ＋ 動詞","ro":"yàak hâi","use":"「（人に）〜してほしい」。อยาก＋動詞「〜したい」との違いは動作をする人。","style":"標準"},{"form":"บอกให้ ＋ 人 ＋ 動詞","ro":"bɔ̀ɔk hâi","use":"「〜するように言う」。指示・頼みを伝える。บอกว่า は内容の伝達。","style":"標準"},{"form":"ปล่อยให้ ＋ 人 ＋ 動詞","ro":"plɔ̀ɔi hâi","use":"「〜させておく・〜するままにする」。止めずに放っておく。","style":"標準"},{"form":"ขอให้ ＋ 文","ro":"khɔ̌ɔ hâi","use":"「〜しますように」。相手の幸運や回復を願う。ขอให้โชคดี「幸運を」。","style":"標準"}],"cases":[{"th":"อยากให้มาเร็ว ๆ","ro":"yàak hâi maa reo reo","ja":"早く来てほしい。","note":"อยากมาเร็ว ๆ だと「自分が早く来たい」になる。"},{"th":"หมอบอกให้พักผ่อน","ro":"mɔ̌ɔ bɔ̀ɔk hâi phák phɔ̀ɔn","ja":"医者に休むように言われた。","note":"日本語の受け身「言われた」も、タイ語では行為者を主語にして บอกให้ で言うことが多い。"},{"th":"ขอโทษที่ให้รอนานนะ","ro":"khɔ̌ɔ thôot thîi hâi rɔɔ naan ná","ja":"長く待たせてごめんね。","note":"「待たせる」は ให้รอ でよい。ปล่อยให้รอ にすると「待たせっぱなしにした」感じが強まる。"},{"th":"ขอให้หายเร็ว ๆ นะ","ro":"khɔ̌ɔ hâi hǎai reo reo ná","ja":"早く治りますように。","note":"病気の人へのお見舞いの決まった言い方。"}],"pitfalls":["「心配させる」「怒らせる」のように気持ちを起こさせるのは ทำให้：ทำให้เป็นห่วง。ให้＋人＋動詞 は人に行動をさせる場合。","ทำให้ は「やってあげる」にもなる：ทำให้ไหม「やってあげようか」。後ろに人の状態や気持ちが来れば「〜にさせる」の意味が多い。","ให้ を文頭に置くと、伝えられた指示を表すことがある：ให้รอตรงนี้「ここで待つように（とのこと）」。"]},"27":{"lead":"「雨で渋滞した」のように出来事が出来事を起こす文では、ทำให้ は説明調に聞こえることがあり、会話では เลย でつなぐことが多くあります。わざとある状態にするなら 動詞＋目的語＋ให้＋状態、度を越した結果なら จน を使います。","compare":[{"form":"原因 ＋ เลย ＋ 結果","ro":"ləəi","use":"「〜で、それで…」。出来事どうしの因果を会話で言うときに普通。","style":"口語"},{"form":"動詞 ＋ 目的語 ＋ ให้ ＋ 状態","ro":"… hâi …","use":"「（意図して）〜を…にする」。ล้างมือให้สะอาด「手をきれいに洗う」。","style":"標準"},{"form":"動詞 ＋ จน ＋ 結果","ro":"con","use":"「…になるほど〜する・〜しすぎて…」。程度が行きついた結果。","style":"標準"}],"cases":[{"th":"ฝนตกเลยรถติด","ro":"fǒn tòk ləəi rót tìt","ja":"雨が降ったから渋滞した。","note":"ฝนตกทำให้รถติด と同じ内容。会話では เลย のほうが多い。"},{"th":"ล้างมือให้สะอาดนะ","ro":"láang mʉʉ hâi sà àat ná","ja":"手をきれいに洗ってね。","note":"意図して状態を作るときは 目的語 を動詞と ให้ の間に置く。"},{"th":"เดินจนขาเจ็บ","ro":"dəən con khǎa cèp","ja":"足が痛くなるほど歩いた。","note":"จน は動作が行きついた結果。"},{"th":"ขอโทษที่ทำให้เป็นห่วง","ro":"khɔ̌ɔ thôot thîi tham hâi pen hùuang","ja":"心配をかけてごめん。","note":"人の気持ちを変えるときは会話でも ทำให้ が自然。"},{"th":"เพลงนี้ทำให้นึกถึงบ้าน","ro":"phleeng níi tham hâi nʉ́k thʉ̌ng bâan","ja":"この歌を聞くと家を思い出す。","note":"「〜すると思い出す」も、物を主語にして ทำให้ で言える。"}],"pitfalls":["「〜しなければならなくなった」は ทำให้ต้อง：ฝนตกทำให้ต้องยกเลิก「雨で中止せざるを得なかった」。","「良くする・改善する」は ทำให้ดีขึ้น のように、変化を表す ขึ้น を添えると自然。","日本語の「雨で」「病気で」の「で」を会話で ด้วย にしない。原因は ทำให้・เลย・เพราะ で表す。"]},"28":{"lead":"น่าจะ と อาจจะ のほかに、会話では คง や文末の มั้ง も多く使います。さらに น่าจะ には「〜すればよかったのに」という意味もあり、推量だと思い込むと誤解します。","compare":[{"form":"น่าจะ ＋ 動詞（済んだこと）","ro":"nâa cà","use":"終わったことについて言うと「〜すべきだった・〜すればよかったのに」という不満や後悔になることが多い。","style":"標準"},{"form":"คง(จะ) ＋ 動詞","ro":"khong (cà)","use":"「たぶん〜だろう」。話し手の推し量りで、否定は คงไม่…。確信が強ければ ต้อง…แน่。","style":"標準"},{"form":"文 ＋ มั้ง","ro":"máng","use":"「〜かな・〜じゃない？」。自信のなさを文末で示すくだけた言い方。","style":"くだけた"}],"cases":[{"th":"น่าจะบอกก่อน","ro":"nâa cà bɔ̀ɔk kɔ̀ɔn","ja":"前もって言ってくれればよかったのに。","note":"終わったことについての น่าจะ は不満・後悔を表すことが多い。"},{"th":"อาจจะไม่ไปก็ได้","ro":"àat cà mâi pai kɔ̂ɔ dâai","ja":"行かないかもしれない。","note":"อาจจะ…ก็ได้ で可能性を残す、よく使う組み合わせ。"},{"th":"พรุ่งนี้คงไม่มีปัญหา","ro":"phrûng níi khong mâi mii pan hǎa","ja":"明日はたぶん問題ないだろう。","note":"คง の否定は คงไม่。ไม่คง とは言わない。"},{"th":"ไม่รู้สิ ไปแล้วมั้ง","ro":"mâi rúu sì pai lɛ́ɛo máng","ja":"さあ、もう行っちゃったんじゃない？","note":"มั้ง は文末に置く。自信がないことを軽く示す。"}],"pitfalls":["น่า＋動詞 は別の語になる：น่ากิน「おいしそう」、น่ารัก「かわいい」。น่าจะ と混同しない。","มั้ง はくだけた言い方なので、目上や仕事の報告では อาจจะ・น่าจะ に ครับ・ค่ะ を付けて言う。","อาจ だけの形は文章で多く、会話では อาจจะ が普通。"]},"29":{"lead":"ถูก と โดน の違いをもう一歩。うれしいことには ได้รับ を使い、そもそもタイ語では受け身の印を付けずに言うほうが自然なことも多くあります。","compare":[{"form":"ถูก","ro":"thùuk","use":"標準的な受け身。迷惑・被害（だまされる・盗まれる・叱られる）が中心。会話でも文章でも使える。","style":"標準"},{"form":"โดน","ro":"doon","use":"会話でいちばんよく使う受け身。ほぼ迷惑・被害の出来事だけ。後ろに名詞も置ける（โดนใบสั่ง「違反切符を切られる」）。","style":"口語"},{"form":"ได้รับ","ro":"dâai ráp","use":"「〜をいただく・受ける」。招待・許可・賞などうれしいこと、中立なことに使う改まった言い方。","style":"改まった表現"},{"form":"เป็นที่ ＋ 動詞","ro":"pen thîi","use":"「（多くの人に）〜されている」。เป็นที่นิยม「人気がある」、เป็นที่รู้จัก「よく知られている」など決まった形。","style":"改まった表現"}],"cases":[{"th":"ผมถูกขโมยกระเป๋าเงิน","ro":"phǒm thùuk khà mooi krà pǎo ngəən","ja":"財布を盗まれました。","note":"日本語と同じく「人＋ถูก＋動詞＋盗まれた物」の順にできる。"},{"th":"ขับรถเร็วเลยโดนใบสั่ง","ro":"khàp rót reo ləəi doon bai sàng","ja":"スピードを出して違反切符を切られた。","note":"โดน は名詞を直接とれる。ถูก ではあまり言わない。"},{"th":"เขาได้รับเชิญไปงานแต่งงาน","ro":"khǎo dâai ráp chəən pai ngaan tɛ̀ng ngaan","ja":"あの人は結婚式に招待された。","note":"うれしい招待には ได้รับเชิญ が自然。ถูกเชิญ とも言えるが、うれしさは出ない。"},{"th":"ร้านนี้เป็นที่นิยมมาก","ro":"ráan níi pen thîi ní yom mâak","ja":"この店はとても人気がある。","note":"「多くの人に好まれている」という受け身の意味を、決まった形で表す。"}],"pitfalls":["日本語の「〜られる」を全部 ถูก にしない。「この寺は300年前に建てられた」は วัดนี้สร้างเมื่อ 300 ปีก่อน のように、受け身の語を付けずに言うのが自然。","ได้รับ はうれしいことが基本だが、報道では ได้รับบาดเจ็บ「けがをする」のように悪いことにも使う決まった言い方がある。","ถูกชม「ほめられる」は言えるが、会話では ครูชม「先生がほめてくれた」のように行為者を主語にするほうが自然なことが多い。","โดน は「当たる・触れる」という動詞でもある：ลูกบอลโดนหัว「ボールが頭に当たった」。โดนใจ は「心に刺さる・ぐっとくる」という口語。"]},"30":{"lead":"文末の助詞を日本語の「ね」「よ」に一つずつ当てはめると、促しが強すぎたり、ふつうの質問が意外そうに聞こえたりします。ここでは สิ のもう一つの使い方、勧めの เถอะ、否定をやわらげる หรอก、問い返しの เหรอ と中立の ไหม の違いを整理します。","compare":[{"form":"สิ","ro":"sì","use":"勧めのほか、「もちろん〜だよ」という当然の答えにも使う。親しい相手向けで、言い方次第ではいら立ちにも聞こえる。","style":"口語"},{"form":"เถอะ","ro":"thə̀","use":"「〜しよう」「〜したら？」。相手に決断を促す勧め。「もうそうしよう」という区切りの感じがある。","style":"口語"},{"form":"หรอก","ro":"rɔ̀ɔk","use":"否定文の終わりに付けて「別に〜じゃないよ」と相手の思い込みをやわらかく打ち消す。","style":"口語"},{"form":"เหรอ ／ ไหม","ro":"rə̌ə / mǎi","use":"เหรอ は聞いたことや見たことへの「そうなの？」。何も前提のない「〜しますか」は ไหม。","style":"口語"}],"cases":[{"th":"ได้สิ","ro":"dâai sì","ja":"もちろんいいよ。","note":"頼まれたときの「当然いいよ」。สิ が「言うまでもない」という気持ちを添える。"},{"th":"ดึกแล้ว กลับบ้านเถอะ","ro":"dʉ̀k lɛ́ɛo klàp bâan thə̀","ja":"もう遅いから帰ろう。","note":"เถอะ は「もうそうしよう」と話をまとめる勧め。"},{"th":"ไม่แพงหรอก","ro":"mâi phɛɛng rɔ̀ɔk","ja":"別に高くないよ。","note":"相手が「高そう」と思っているのを打ち消す。หรอก がないと単なる事実の報告。"},{"th":"กินกาแฟไหม","ro":"kin kaa fɛɛ mǎi","ja":"コーヒー飲む？","note":"何も前提のない誘い・質問は ไหม。"},{"th":"กินกาแฟเหรอ","ro":"kin kaa fɛɛ rə̌ə","ja":"コーヒー飲むの？","note":"相手がコーヒーを飲むと知って・見て、意外さや確認を込めて聞き返す形。"}],"pitfalls":["หรอก は基本的に否定文（ไม่…หรอก・ไม่ใช่หรอก）で使う。肯定文の「〜だよ」に付けない。","สิ を目上やお客に使うと命令口調に聞こえやすい。丁寧に頼むなら ช่วย…หน่อยนะครับ／คะ のほうが安全。","นะ は丁寧語の前に置く：ขอบคุณนะครับ（○）。話し言葉では声を伸ばした น้า の形もある。"]},"31":{"lead":"日本語の「の」をいつも ของ に置き換えると、家族や体を言うときに硬く聞こえ、「タイ語の先生」のような種類・所属の「の」では意味が変わってしまいます。ここでは ของ を省く場合、使わない場合、名詞の ของ「物」、改まった แห่ง を整理します。","compare":[{"form":"名詞 ＋ 持ち主（ของ なし）","ro":"—","use":"家族・友人・体の部分・家・会社など、切り離せない関係では ของ を省くことが多い：พ่อผม「僕の父」、บ้านผม「僕の家」。","style":"標準"},{"form":"名詞 ＋ 名詞（種類・所属）","ro":"—","use":"「タイ語の先生」「日本の車」のような種類・所属の「の」は ของ を使わず名詞を並べる：ครูภาษาไทย、รถญี่ปุ่น。","style":"標準"},{"form":"名詞 ＋ แห่ง ＋ 名詞","ro":"hɛ̀ng","use":"「〜の」の改まった形。機関名や書名などで使う：ธนาคารแห่งประเทศไทย「タイ銀行」。会話ではまず使わない。","style":"文語"}],"cases":[{"th":"พ่อผมเป็นหมอ","ro":"phɔ̂ɔ phǒm pen mɔ̌ɔ","ja":"僕の父は医者です。","note":"家族には ของ を付けないのが自然。พ่อของผม は説明的で硬い感じになりやすい。"},{"th":"รถคันนี้ของใคร","ro":"rót khan níi khɔ̌ɔng khrai","ja":"この車は誰の？","note":"持ち主を尋ねるときは ของ が必要。類別詞の คันนี้ は名詞のすぐ後ろ。"},{"th":"นี่ของผม ไม่ใช่ของคุณ","ro":"nîi khɔ̌ɔng phǒm mâi châi khɔ̌ɔng khun","ja":"これは僕のだよ。あなたのじゃない。","note":"持ち主を対比するときは ของ をはっきり言う。"},{"th":"เขาเป็นครูภาษาไทย","ro":"khǎo pen khruu phaa sǎa thai","ja":"あの人はタイ語の先生です。","note":"種類の「の」なので ของ は入れない。ครูของภาษาไทย とは言わない。"},{"th":"ซื้อของฝากให้เพื่อน","ro":"sʉ́ʉ khɔ̌ɔng fàak hâi phʉ̂ʉan","ja":"友達にお土産を買う。","note":"ของ は名詞で「物」にもなる。ของฝาก「お土産」、ของกิน「食べ物」。"}],"pitfalls":["「私の好きな料理」は อาหารที่ผมชอบ。動詞が続く「の」は ของ ではなく ที่ でつなぐ。","借りた物・預かった物など、誰の物かを区別したいときは ของ を入れるほうが誤解がない。"]},"32":{"lead":"日本語の「〜してもいいですか」と「〜してもらえますか」はどちらも ได้ไหม で終わりますが、タイ語では誰が動くかで ขอ と ช่วย を使い分けます。ここではその区別と、改まった ขออนุญาต、ได้ を落としたときの意味の変化を整理します。","compare":[{"form":"ขอ ＋ 動詞 ＋ หน่อย","ro":"khɔ̌ɔ … nɔ̀ɔi","use":"ได้ไหม を付けず「ちょっと〜させてね」と軽く断る言い方。ขอผ่านหน่อย「ちょっと通してください」など。","style":"口語"},{"form":"ช่วย ＋ 動詞 ＋ (ให้) หน่อยได้ไหม","ro":"chûuai … (hâi) nɔ̀ɔi dâai mǎi","use":"相手に動いてもらう依頼。「〜してもらえますか」。ให้ を入れると「私のために」の意味がはっきりする。","style":"標準"},{"form":"ขออนุญาต ＋ 動詞","ro":"khɔ̌ɔ à nú yâat","use":"「〜させていただきます・よろしいでしょうか」。仕事や目上への改まった許可の求め方。","style":"改まった表現"}],"cases":[{"th":"ช่วยถ่ายรูปให้หน่อยได้ไหม","ro":"chûuai thàai rûup hâi nɔ̀ɔi dâai mǎi","ja":"写真を撮ってもらえますか。","note":"撮るのは相手。ขอถ่ายรูปได้ไหม「撮ってもいいですか」と ขอ／ช่วย だけで逆になる。"},{"th":"ขอดูหน่อยได้ไหม","ro":"khɔ̌ɔ duu nɔ̀ɔi dâai mǎi","ja":"ちょっと見せてもらえますか。","note":"日本語の「見せて」も、タイ語では自分が「見る」許可として ขอดู で言うのがふつう。"},{"th":"ขอผ่านหน่อยครับ","ro":"khɔ̌ɔ phàan nɔ̀ɔi khráp","ja":"ちょっと通してください。","note":"混んだ場所での決まった言い方。答えを待たずに動いてよい。"},{"th":"ขออนุญาตเข้าไปนะคะ","ro":"khɔ̌ɔ à nú yâat khâo pai ná khá","ja":"失礼して、中に入りますね。","note":"改まった場面で、ことわりを入れてから動く言い方。"}],"pitfalls":["ได้ を落とすと別の意味になる：นั่งตรงนี้ไหม は「ここに座る？」という相手への勧め。許可を聞くなら นั่งตรงนี้ได้ไหม。","許可への答えは ได้ครับ／ได้ค่ะ、「どうぞ」なら เชิญครับ／เชิญค่ะ。断るときは ไม่ได้ だけだと強いので、ขอโทษนะ を添える。","ขอตัว「（席を外して）失礼します」も ขอ を使った決まった言い方。"]},"33":{"lead":"เพิ่ง と ใกล้จะ だけでは、「まだ9時だよ」の軽さや、「今出るところ」「危うく〜するところだった」の言い分けができません。เพิ่ง…เอง、กำลังจะ、ใกล้＋名詞、เกือบ との違いを整理します。","compare":[{"form":"เพิ่ง … เอง","ro":"phə̂əng … eeng","use":"「まだ〜したばかりだよ・まだ〜にすぎない」。時間や量が少ないことを強める。時刻と使うと「まだ〜時だよ」。","style":"口語"},{"form":"กำลังจะ ＋ 動詞","ro":"kam lang cà","use":"「今まさに〜するところ」。動作の直前。","style":"標準"},{"form":"ใกล้ ＋ 名詞 ＋ แล้ว","ro":"klâi … lɛ́ɛo","use":"「もうすぐ〜だ」。時期や行事の名詞を直接続ける。","style":"標準"},{"form":"เกือบ ＋ 動詞","ro":"kʉ̀ʉap","use":"「危うく〜するところだった・ほとんど〜」。実際には起きなかった、またはわずかに届かなかったこと。","style":"標準"}],"cases":[{"th":"เพิ่งรู้","ro":"phə̂əng rúu","ja":"今知った（知らなかった）。","note":"日本語の「知らなかった」は、タイ語ではよく เพิ่งรู้「今初めて知った」と言う。"},{"th":"เพิ่งสามทุ่มเอง","ro":"phə̂əng sǎam thûm eeng","ja":"まだ夜9時だよ。","note":"時刻と使うと「まだ早い」という気持ち。動詞がなくても言える。"},{"th":"กำลังจะออกจากบ้าน","ro":"kam lang cà ɔ̀ɔk càak bâan","ja":"今ちょうど家を出るところ。","note":"動作の直前は กำลังจะ。"},{"th":"ใกล้ปีใหม่แล้ว","ro":"klâi pii mài lɛ́ɛo","ja":"もうすぐ新年だ。","note":"時期の名詞なら ใกล้＋名詞 が簡潔。ใกล้จะถึงปีใหม่แล้ว とも言う。"},{"th":"เกือบลืม","ro":"kʉ̀ʉap lʉʉm","ja":"危うく忘れるところだった。","note":"実際には忘れていない。「もうちょっとで〜だった」は เกือบ。"}],"pitfalls":["日本語の「もうすぐ」に引かれて何でも ใกล้จะ にしない。動作の直前は กำลังจะ、時期は ใกล้＋名詞、「危うく〜だった」は เกือบ。","เพิ่ง は動詞の前に置く。日本語の「ばかり」のように文の後ろには来ない：เพิ่งกิน（○）。","「さっき〜した」と言うとき、เพิ่ง の文には แล้ว より ไป を添えることが多い：เพิ่งกินไป「さっき食べたところ」。"]},"34":{"lead":"日本語の「〜しないで」は、タイ語では「やめて」の อย่า と「その必要はない」の ไม่ต้อง に分かれます。ここでは ไม่ต้อง、อย่าเพิ่ง「まだ〜しないで」、動詞の ห้าม、掲示の กรุณาอย่า を整理します。","compare":[{"form":"ไม่ต้อง ＋ 動詞","ro":"mâi tɔ̂ɔng","use":"「〜しなくていい」。気づかいの「心配しないで」「遠慮しないで」に向く。","style":"標準"},{"form":"อย่าเพิ่ง ＋ 動詞","ro":"yàa phə̂əng","use":"「まだ〜しないで」。今はやめて、あとならよいという意味。","style":"標準"},{"form":"人 ＋ ห้าม（ไม่ให้）＋ 動詞","ro":"hâam (mâi hâi)","use":"「〜するなと禁じる・止める」。ห้าม が動詞として人の行動を止める。","style":"標準"},{"form":"กรุณาอย่า ／ โปรดอย่า ＋ 動詞","ro":"kà rú naa yàa ／ pròot yàa","use":"「〜しないでください」。掲示・アナウンスの丁寧な禁止。","style":"改まった表現"}],"cases":[{"th":"ไม่ต้องห่วง","ro":"mâi tɔ̂ɔng hùuang","ja":"心配しないで。","note":"「心配する必要はない」と相手を安心させる。อย่าห่วงนะ とも言えるが、ไม่ต้อง のほうがやわらかい。"},{"th":"ไม่ต้องเกรงใจ","ro":"mâi tɔ̂ɔng kreeng cai","ja":"遠慮しないで。","note":"気づかいの「〜しないで」は ไม่ต้อง がふつう。"},{"th":"อย่าเพิ่งไปนะ","ro":"yàa phə̂əng pai ná","ja":"まだ行かないでね。","note":"เพิ่ง が入ると「今はまだ」の意味になる。"},{"th":"แม่ห้ามไม่ให้ออกไปข้างนอก","ro":"mɛ̂ɛ hâam mâi hâi ɔ̀ɔk pai khâang nɔ̂ɔk","ja":"母は外に出ることを禁じている。","note":"ห้าม が動詞「禁じる」。ไม่ให้ は否定の重なりではなく「〜しないように」の意味。"},{"th":"กรุณาอย่าส่งเสียงดัง","ro":"kà rú naa yàa sòng sǐiang dang","ja":"大きな声を出さないでください。","note":"図書館や病院の掲示などで見る丁寧な禁止。"}],"pitfalls":["ไม่ だけでは禁止にならない：ไม่ไป は「行かない」で、「行くな」は อย่าไป。","目上に อย่า を単独で使うと命令に聞こえる。อย่า…นะครับ／คะ と添えるか、ไม่ต้อง…ก็ได้ครับ「〜しなくても大丈夫です」と言い換える。","อย่าเลย は「やめておこう・やめたほうがいい」と止める決まった言い方。","ไม่ต้องมา＋動詞 は「〜してこないで」と突き放す強い言い方になる：ไม่ต้องมายุ่ง「口出ししないで」。"]},"35":{"lead":"日本語の「〜けど」は前置きにも使いますが、タイ語の แต่ は対比があるときの語です。ここでは改まった ถึงแม้ว่า、「〜なのは確かだが」の ก็จริงแต่、話題を対比する ส่วน、「それでも」の แต่ก็ を加えます。","compare":[{"form":"ถึงแม้ว่า … （แต่）… ก็ …","ro":"thʉ̌ng mɛ́ɛ wâa","use":"「〜ではあるが・たとえ〜でも」。ถึง の改まった形。文章やニュースで多い。後半に แต่ を重ねることもある。","style":"改まった表現"},{"form":"… ก็จริง แต่ …","ro":"kɔ̂ɔ cing tɛ̀ɛ","use":"「〜なのは確かだけど」。相手の言い分を認めてから反論する。","style":"標準"},{"form":"ส่วน","ro":"sùuan","use":"「一方〜は」。二人・二つの話題を並べて対比する。日本語の対比の「は」に近い。","style":"標準"},{"form":"แต่ก็","ro":"tɛ̀ɛ kɔ̂ɔ","use":"「でも、それでも」。マイナス面を認めたうえで、プラス面や結果を続ける。","style":"標準"}],"cases":[{"th":"ถึงแม้ว่าเขาจะรวย แต่เขาก็ไม่มีความสุข","ro":"thʉ̌ng mɛ́ɛ wâa khǎo cà ruuai tɛ̀ɛ khǎo kɔ̂ɔ mâi mii khwaam sùk","ja":"あの人はお金持ちではあるが、幸せではない。","note":"ถึงแม้ว่า と แต่ を一文で一緒に使える。後半の ก็ は主語の後ろ。"},{"th":"แพงก็จริง แต่คุ้ม","ro":"phɛɛng kɔ̂ɔ cing tɛ̀ɛ khúm","ja":"高いのは確かだけど、値打ちはある。","note":"まず認めてから、言いたいことを แต่ の後ろに置く。"},{"th":"แพงไปหน่อย แต่ก็อร่อยดี","ro":"phɛɛng pai nɔ̀ɔi tɛ̀ɛ kɔ̂ɔ à rɔ̀ɔi dii","ja":"ちょっと高すぎるけど、それでもおいしい。","note":"แต่ก็ でマイナスを受け止めてプラスを続ける。"},{"th":"พี่ชอบกาแฟ ส่วนน้องชอบชา","ro":"phîi chɔ̂ɔp kaa fɛɛ sùuan nɔ́ɔng chɔ̂ɔp chaa","ja":"兄（姉）はコーヒーが好きで、弟（妹）はお茶が好き。","note":"แต่ でも言えるが、ส่วน は「〜のほうは」と話題を切り替えるだけで、逆接の響きが弱い。"},{"th":"ช่วงนี้กินแต่ผัก","ro":"chûuang níi kin tɛ̀ɛ phàk","ja":"最近は野菜ばかり食べている。","note":"動詞の後ろの แต่ は「〜ばかり・〜だけ」で、逆接ではない。"}],"pitfalls":["日本語の前置きの「〜けど」「〜が」（「すみませんが」「トイレに行きたいんですけど」）を แต่ にしない。対比がなければ ขอโทษครับ や ขอไปเข้าห้องน้ำหน่อย のように直接言う。","ถึง…ก็ の ก็ は後半の主語の後ろ、動詞の前：ถึงฝนตก เขาก็จะไป（○）／ ถึงฝนตก ก็เขาจะไป（×）。","เอาแต่＋動詞 は「〜してばかりいる」と不満を込めた言い方：เอาแต่เล่นเกม「ゲームばかりしている」。"]},"36":{"lead":"日本語の「〜くなる・〜になる」を全部 ขึ้น・ลง で言おうとすると、名詞の「〜になる」は言えず、今の状態に気づいただけの「暗くなった」も遠回りになります。ขึ้น と ลง の選び方の傾向と、เริ่ม…แล้ว・แล้ว・กลายเป็น との違いを整理します。","compare":[{"form":"形容詞 ＋ ขึ้น ／ ลง","ro":"khʉ̂n ／ long","use":"量や程度が増えるなら ขึ้น（อ้วนขึ้น・โตขึ้น）、減るなら ลง（ผอมลง・น้อยลง）。良し悪しでは ดีขึ้น・แย่ลง の組が多い。","style":"標準"},{"form":"เริ่ม ＋ 形容詞 ＋ แล้ว","ro":"rə̂əm … lɛ́ɛo","use":"「〜くなってきた」。変化が始まったところ。天気や体調によく使う。","style":"標準"},{"form":"形容詞 ＋ แล้ว","ro":"lɛ́ɛo","use":"「（もう）〜になった」。比べるより、今その状態だと気づいたことを言う。","style":"標準"},{"form":"เป็น ／ กลายเป็น ＋ 名詞","ro":"pen ／ klaai pen","use":"名詞の「〜になる」。กลายเป็น は「〜に変わる・〜になってしまう」と変化の結果を言う。ขึ้น・ลง は名詞に付かない。","style":"標準"}],"cases":[{"th":"อากาศเริ่มเย็นแล้ว","ro":"aa kàat rə̂əm yen lɛ́ɛo","ja":"涼しくなってきた。","note":"変化の始まり。เย็นลง・เย็นขึ้น とすると「前より涼しくなった」と比べる言い方になる。"},{"th":"มืดแล้ว","ro":"mʉ̂ʉt lɛ́ɛo","ja":"暗くなった。","note":"日本語の「〜なった」でも、今の状態を言うだけなら แล้ว で足りる。"},{"th":"โตขึ้นอยากเป็นอะไร","ro":"too khʉ̂n yàak pen à rai","ja":"大きくなったら何になりたい？","note":"ขึ้น は形容詞の変化、名詞の「〜になる」は เป็น。子どもによく聞く決まった質問。"},{"th":"พูดช้าลงหน่อยได้ไหม","ro":"phûut cháa long nɔ̀ɔi dâai mǎi","ja":"もう少しゆっくり話してもらえますか。","note":"依頼でも ขึ้น・ลง で「今より」を表す。พูดดังขึ้นหน่อย「もう少し大きな声で」。"},{"th":"เขากลายเป็นนักร้องดัง","ro":"khǎo klaai pen nák rɔ́ɔng dang","ja":"あの人は有名な歌手になった。","note":"名詞の「〜になる」なので กลายเป็น。ดังขึ้น なら「前より有名になった」。"}],"pitfalls":["どちらを付けるかは語ごとに傾向がある：แย่ลง「悪くなる」（แย่ขึ้น とはあまり言わない）。迷ったら組で覚える。","動作の動詞の後ろの ขึ้น・ลง は方向を表す：เดินขึ้น「歩いて上がる」、นั่งลง「座る」。形容詞の後ろなら程度の変化。"]},"37":{"lead":"日本語の「〜ために」をいつも เพื่อ にすると、「買いに行く」のような移動の目的で硬く聞こえます。動詞を並べる形、他の人がそうなるように願う เพื่อให้、用途の สำหรับ、「〜用に取っておく」の ไว้ を整理します。","compare":[{"form":"ไป ／ มา ＋ 動詞","ro":"pai ／ maa","use":"「〜しに行く・来る」。移動の目的は動詞を並べるだけで、เพื่อ は付けないのがふつう。","style":"標準"},{"form":"เพื่อให้ ＋ 結果","ro":"phʉ̂ʉa hâi","use":"「〜するように・〜になるように」。起きてほしい結果を言う。他の人や物事が主語になるときは เพื่อให้ を使い、その主語を後ろに置く。","style":"標準"},{"form":"สำหรับ ＋ 名詞","ro":"sǎm ràp","use":"「〜用・〜向け」。物の用途や対象を言う。人の行動の目的には เพื่อ。","style":"標準"},{"form":"動詞 ＋ ไว้ ＋ 動詞","ro":"wái","use":"「〜するために取っておく」。先の目的のために準備しておく。","style":"標準"}],"cases":[{"th":"ไปตลาดซื้อผลไม้","ro":"pai tà làat sʉ́ʉ phǒn lá máai","ja":"市場へ果物を買いに行く。","note":"移動の目的は動詞を並べるだけ。เพื่อ を入れると説明文のように硬い。"},{"th":"พูดช้าๆ เพื่อให้ทุกคนเข้าใจ","ro":"phûut cháa cháa phʉ̂ʉa hâi thúk khon khâo cai","ja":"みんなにわかるようにゆっくり話す。","note":"わかるのは聞き手なので เพื่อให้。"},{"th":"ห้องนี้สำหรับนักเรียน","ro":"hɔ̂ɔng níi sǎm ràp nák riian","ja":"この部屋は学生用です。","note":"用途・対象は สำหรับ。เพื่อนักเรียน とすると「学生の利益のために」という意味に寄る。"},{"th":"เก็บเงินไว้ใช้ตอนแก่","ro":"kèp ngəən wái chái tɔɔn kɛ̀ɛ","ja":"年をとってから使うためにお金を取っておく。","note":"ไว้ で「先のために取っておく」。"},{"th":"พ่อทำงานหนักเพื่อลูก","ro":"phɔ̂ɔ tham ngaan nàk phʉ̂ʉa lûuk","ja":"父は子どものために一生懸命働く。","note":"เพื่อ＋人 は「その人のために（尽くす）」。"}],"pitfalls":["日本語の「〜のために」は理由にもなる（「雨のために中止」）。理由なら เพราะ（ยกเลิกเพราะฝนตก）で、เพื่อ は使えない。","จะได้ は後ろの文の頭に置く：ตื่นเช้า จะได้ไม่สาย（○）。「〜できるように」を先に言いたいときは เพื่อ を使う。"]},"38":{"lead":"日本語の「〜たら」「〜とき」は、タイ語では続きの พอ…ก็、習慣の เวลา、最中の ระหว่าง、条件の ถ้า などに分かれます。タイ語の動詞は「行くとき／行ったとき」で形が変わらないので、前後は言葉で補います。","compare":[{"form":"พอ … ก็ …","ro":"phɔɔ … kɔ̂ɔ","use":"「〜したら（すぐ）・〜すると」。一つの出来事のすぐ後に次が起きる。会話でとてもよく使う。","style":"標準"},{"form":"เวลา …","ro":"wee laa","use":"「〜するときは（いつも）」。くり返しや習慣の「とき」。","style":"標準"},{"form":"ระหว่าง（ที่）／ ขณะที่ …","ro":"rá wàang (thîi) ／ khà nà thîi","use":"「〜している間・〜している最中に」。ขณะที่ は文章や報道で多い。","style":"標準"},{"form":"ตอน ＋ 名詞","ro":"tɔɔn","use":"「〜のころ・〜のとき」。ตอนเด็ก「子どものころ」、ตอนเช้า「朝」のように名詞に直接付ける。","style":"標準"}],"cases":[{"th":"พอถึงบ้านก็หลับเลย","ro":"phɔɔ thʉ̌ng bâan kɔ̂ɔ làp ləəi","ja":"家に着いたらすぐ寝てしまった。","note":"พอ…ก็ は「〜したとたんに」という続き。เมื่อ より会話的。"},{"th":"เวลาเครียดผมชอบฟังเพลง","ro":"wee laa khrîiat phǒm chɔ̂ɔp fang phleeng","ja":"ストレスがたまったときは、音楽を聴くのが好きだ。","note":"「そういうときはいつも」という習慣の เวลา。"},{"th":"ระหว่างรอ อ่านหนังสือไปก่อน","ro":"rá wàang rɔɔ àan nǎng sʉ̌ʉ pai kɔ̀ɔn","ja":"待っている間、先に本を読んでいて。","note":"最中の「間」は ระหว่าง。"},{"th":"ตอนเด็กผมอยู่ต่างจังหวัด","ro":"tɔɔn dèk phǒm yùu tàang cang wàt","ja":"子どものころ、地方に住んでいた。","note":"ตอน＋名詞で「〜のころ」。"},{"th":"ถ้าฝนตกจะไม่ไป","ro":"thâa fǒn tòk cà mâi pai","ja":"雨が降ったら行かない。","note":"降るかどうかわからないので ถ้า。"}],"pitfalls":["日本語の「〜たら」を全部 ถ้า にしない。必ず起きることの「着いたら電話する」は ถึงแล้วจะโทรหา や พอถึงก็จะโทรหา のように言うことが多い。","ตอนไปญี่ปุ่น は「日本へ行くとき」とも「日本へ行ったとき」とも取れる。前後をはっきりさせるなら ก่อนไป、ตอนอยู่ที่ญี่ปุ่น、หลังจากกลับมา のように言い分ける。","หลัง は名詞に直接付けられる：หลังอาหาร「食後」、หลังเลิกงาน「仕事のあと」。จาก を付けない形も会話ではよく使う。"]},"39":{"lead":"จึง と ดังนั้น は書き言葉の「だから」で、会話では ก็เลย・เลย・เพราะฉะนั้น が中心です。จึงจะ のように「〜して初めて」という条件を表す形も押さえます。","compare":[{"form":"（主語）＋ ก็เลย／เลย ＋ 動詞","ro":"kɔ̂ɔ ləəi ／ ləəi","use":"会話の「それで・だから」。いちばんよく使い、เลย だけでも言える。主語は ก็เลย の前に置く。","style":"口語"},{"form":"เพราะฉะนั้น","ro":"phrɔ́ chà nán","use":"「だから・そういうわけで」。文の頭に置く。会話でも説明や説得の場面でよく使う。","style":"標準"},{"form":"ต้อง … จึงจะ …","ro":"tɔ̂ɔng … cʉng cà","use":"「〜して初めて…できる・〜しないと…できない」。結果ではなく条件を表す。","style":"改まった表現"}],"cases":[{"th":"ฝนตก ก็เลยไม่ได้ไป","ro":"fǒn tòk kɔ̂ɔ ləəi mâi dâai pai","ja":"雨が降ったから行かなかった。","note":"友人との会話ならこの形。ここで จึง を使うと作文を読み上げたように硬い。"},{"th":"เมื่อคืนนอนดึก เลยตื่นสาย","ro":"mʉ̂ʉa khʉʉn nɔɔn dʉ̀k ləəi tʉ̀ʉn sǎai","ja":"昨夜遅く寝たので寝坊した。","note":"ก็ を省いた เลย だけの形。会話でとても多い。"},{"th":"พรุ่งนี้ต้องตื่นเช้า เพราะฉะนั้นวันนี้นอนเร็วหน่อยนะ","ro":"phrûng níi tɔ̂ɔng tʉ̀ʉn cháao phrɔ́ chà nán wan níi nɔɔn reo nɔ̀ɔi ná","ja":"明日は早起きしないといけない。だから今日は早めに寝てね。","note":"เพราะฉะนั้น は理由を示して相手に何かを勧めるときによく使う。"},{"th":"เพราะเขาช่วย ผมจึงทำงานเสร็จทันเวลา","ro":"phrɔ́ khǎo chûuai phǒm cʉng tham ngaan sèt than wee laa","ja":"あの人が手伝ってくれたので、私は期限内に仕事を終えられた。","note":"เพราะ…จึง… の組み合わせ。報告やメールで使う改まった形。"},{"th":"ต้องมีหนังสือเดินทาง จึงจะขึ้นเครื่องได้","ro":"tɔ̂ɔng mii nǎng sʉ̌ʉ dəən thaang cʉng cà khʉ̂n khrʉ̂ʉang dâai","ja":"パスポートがあって初めて飛行機に乗れる。","note":"ต้อง…จึงจะ… は「だから」ではなく条件。จึง の後ろに จะ があるかどうかを確かめる。"}],"pitfalls":["ก็เลย・จึง は主語の後ろ、ดังนั้น・เพราะฉะนั้น は主語の前に置く：ผมจึงไป（○）／ จึงผมไป（×）。","文末の เลย は「だから」ではない：อร่อยมากเลย「すごくおいしい」、ไม่เข้าใจเลย「全然わからない」。「だから」の เลย は動詞の前に来る。","日本語の「だから言ったでしょ」のような言い返しの「だから」は ก็เลย・จึง では言わない。会話では ก็บอกแล้วไง のように言う。"]},"40":{"lead":"日本語の「〜ても」「〜のに」は、タイ語では文体と「事実か仮定か」で言い方が分かれます。会話の ถึง と改まった แม้ว่า の差、強めた ทั้งๆ ที่、形の似た แม้แต่・ทั้งที との取り違えを押さえます。","compare":[{"form":"ถึง（จะ）＋ 条件 ＋ ก็ ＋ 結果","ro":"thʉ̌ng (cà) … kɔ̂ɔ","use":"「〜ても」。会話ではふつうこちらを使う。แม้ว่า は報道・スピーチ・文章向き。","style":"口語"},{"form":"ทั้งๆ ที่ ＋ 事実","ro":"tháng tháng thîi","use":"ทั้งที่ を重ねて強めた会話形。「実際〜なのに」と、いら立ちや驚きがにじむ。","style":"口語"},{"form":"ถึงอย่างนั้น","ro":"thʉ̌ng yàang nán","use":"文の頭で「それでも」。前の話全体を受ける。会話では อย่างไรก็ตาม よりこちらが多い。","style":"標準"},{"form":"แม้แต่ ＋ 名詞 ＋ ก็","ro":"mɛ́ɛ tɛ̀ɛ … kɔ̂ɔ","use":"「〜でさえ」。「〜ても」の แม้ とは別の使い方。","style":"標準"}],"cases":[{"th":"ถึงจะแพง ก็อยากซื้อ","ro":"thʉ̌ng cà phɛɛng kɔ̂ɔ yàak sʉ́ʉ","ja":"高くても買いたい。","note":"会話では แม้ว่า より ถึง が自然。"},{"th":"ทั้งๆ ที่บอกแล้ว เขาก็ยังลืม","ro":"tháng tháng thîi bɔ̀ɔk lɛ́ɛo khǎo kɔ̂ɔ yang lʉʉm","ja":"言っておいたのに、それでもあの人は忘れた。","note":"実際に言ったという事実を受ける。いら立ちがにじむ。"},{"th":"ถึงอย่างนั้น ผมก็ยังเชื่อเขา","ro":"thʉ̌ng yàang nán phǒm kɔ̂ɔ yang chʉ̂ʉa khǎo","ja":"それでも、私はあの人を信じている。","note":"前の話全体を受ける会話的な接続。"},{"th":"แม้แต่เด็กก็รู้","ro":"mɛ́ɛ tɛ̀ɛ dèk kɔ̂ɔ rúu","ja":"子どもでさえ知っている。","note":"แม้แต่＋名詞は「〜でさえ」。"},{"th":"มาทั้งที ต้องลองหน่อย","ro":"maa tháng thii tɔ̂ɔng lɔɔng nɔ̀ɔi","ja":"せっかく来たんだから、試してみなきゃ。","note":"ทั้งที は「せっかく〜なのだから」。"}],"pitfalls":["ทั้งที่（tháng thîi「〜なのに」）と ทั้งที（tháng thii「せっかく」）は、声調が一つ違うだけの別の言葉。","ยังไงก็＋動詞 は「どっちにしても・何があっても」：ยังไงก็ต้องไป「どっちにしても行かなきゃ」。"]},"41":{"lead":"日本語の「〜で」「〜によって」は一つで何でも表せますが、タイ語では道具なら ด้วย、連絡の手段なら ทาง、方法なら โดย と分かれます。ซึ่ง で前の内容を言い換える ซึ่งก็คือ も加えます。","compare":[{"form":"ซึ่งก็คือ","ro":"sʉ̂ng kɔ̂ɔ khʉʉ","use":"「つまり・それは〜だ」。前の内容を言い換えて補う。","style":"改まった表現"},{"form":"動詞 ＋ ด้วย ＋ 道具・材料","ro":"dûuai","use":"「〜で（道具）」。手・ペン・はさみなど。กินด้วยมือ「手で食べる」。","style":"標準"},{"form":"ทาง ＋ 連絡手段","ro":"thaang","use":"「〜で（連絡する）」。ทางโทรศัพท์「電話で」、ทางอีเมล「メールで」。","style":"標準"},{"form":"โดยการ ／ โดยไม่ ＋ 動詞","ro":"dooi kaan ／ dooi mâi","use":"「〜することで」「〜せずに」。โดยไม่ は会話でもよく使う。","style":"標準"}],"cases":[{"th":"งานจะจัดวันเสาร์นี้ ซึ่งก็คือวันเกิดของแม่","ro":"ngaan cà càt wan sǎo níi sʉ̂ng kɔ̂ɔ khʉʉ wan kə̀ət khɔ̌ɔng mɛ̂ɛ","ja":"会は今度の土曜日、つまり母の誕生日に開く。","note":"ซึ่งก็คือ で前の内容を言い換えて補う。"},{"th":"กรุณาเขียนด้วยปากกาสีน้ำเงิน","ro":"kà rú naa khǐian dûuai pàak kaa sǐi nám ngəən","ja":"青いペンで書いてください。","note":"道具は ด้วย。ここを โดย にすると不自然。"},{"th":"ติดต่อทางอีเมลได้","ro":"tìt tɔ̀ɔ thaang ii meel dâai","ja":"メールで連絡できます。","note":"連絡の手段は ทาง が多い。"},{"th":"ลดน้ำหนักโดยการออกกำลังกาย","ro":"lót nám nàk dooi kaan ɔ̀ɔk kam lang kaai","ja":"運動することで減量する。","note":"方法を表す โดยการ＋動詞。"},{"th":"เขาออกไปโดยไม่บอกใคร","ro":"khǎo ɔ̀ɔk pai dooi mâi bɔ̀ɔk khrai","ja":"あの人は誰にも言わずに出て行った。","note":"โดยไม่＋動詞で「〜せずに」。"}],"pitfalls":["「〜で」を全部 โดย にしない。道具は ด้วย、場所の「〜で」は ที่（ทำงานที่บริษัท「会社で働く」）、乗り物は นั่ง・ขึ้น。","「〜によって書かれた」をそのまま訳すと翻訳調になりやすい。会話では นักเขียนคนนี้เขียน「この作家が書いた」のように行為者を主語にすることが多い。","โดย は決まった副詞にもなる：โดยเฉพาะ「特に」、โดยทั่วไป「一般に」。ผมชอบผลไม้ไทย โดยเฉพาะมะม่วง「タイの果物、特にマンゴーが好き」。"]},"42":{"lead":"日本語の「ますます」「どんどん」を全部 ยิ่ง にすると不自然になります。原因を言わない変化の ขึ้นเรื่อยๆ、決まり文句の ยิ่ง…ยิ่งดี、改まった ยิ่งขึ้น、比較の ยิ่งกว่า を区別します。","compare":[{"form":"ยิ่ง ＋ 形容詞 ＋ ยิ่งดี","ro":"yîng … yîng dii","use":"「〜であればあるほどいい」。ยิ่งเร็วยิ่งดี「早いほどいい」などの決まった言い方。","style":"標準"},{"form":"動詞・形容詞 ＋ ขึ้นเรื่อยๆ","ro":"khʉ̂n rʉ̂ʉai rʉ̂ʉai","use":"「どんどん・だんだん〜になる」。原因を言わず、変化が続くことだけを表す。","style":"標準"},{"form":"形容詞 ＋ ยิ่งขึ้น","ro":"yîng khʉ̂n","use":"「さらに・いっそう〜に」。目標や約束を述べる改まった言い方。","style":"改まった表現"},{"form":"形容詞 ＋ ยิ่งกว่า ＋ 名詞","ro":"yîng kwàa","use":"「〜以上に・〜よりさらに」。กว่า より強い比較。","style":"標準"}],"cases":[{"th":"ยิ่งเร็วยิ่งดี","ro":"yîng reo yîng dii","ja":"早ければ早いほどいい。","note":"頼みごとや予定でよく使う決まった言い方。"},{"th":"ยิ่งห้ามยิ่งอยากทำ","ro":"yîng hâam yîng yàak tham","ja":"禁止されるほどやりたくなる。","note":"受け身の印がなくても「禁止される」と読める。"},{"th":"อากาศร้อนขึ้นเรื่อยๆ","ro":"aa kàat rɔ́ɔn khʉ̂n rʉ̂ʉai rʉ̂ʉai","ja":"どんどん暑くなっている。","note":"比例の原因がないので ยิ่ง…ยิ่ง… は使わない。"},{"th":"เราจะพัฒนาบริการให้ดียิ่งขึ้น","ro":"rao cà phát thá naa bɔɔ rí kaan hâi dii yîng khʉ̂n","ja":"サービスをさらに良くしてまいります。","note":"企業の案内やスピーチで多い ยิ่งขึ้น。"},{"th":"เขาเก่งยิ่งกว่าครูอีก","ro":"khǎo kèng yîng kwàa khruu ìik","ja":"あの人は先生以上に上手だ。","note":"ยิ่งกว่า…อีก で「〜よりさらに上」と驚きを込める。"}],"pitfalls":["日本語の「〜ば〜ほど」の「ば」につられて ถ้า を付けない。ยิ่ง が二つあれば条件の意味は出る。","二つ目の ยิ่ง を落とさない。ยิ่งเรียน สนุก のように片方だけでは文として不自然。","ยิ่งใหญ่（yîng yài）は「偉大な・壮大な」という一語の形容詞で、比例の ยิ่ง とは別。"]},"43":{"lead":"ไม่ว่า…ก็… は「〜であろうと」の少し改まった形で、会話では「何でもいい」の 疑問詞＋ก็ได้ もよく使います。「何でもない」「誰も〜ない」との違いや、ไม่ว่า が「とがめない」の意味になる場合にも注意します。","compare":[{"form":"疑問詞 ＋ ก็ได้","ro":"… kɔ̂ɔ dâai","use":"「何でも・どこでも・いつでもいい」。好みを聞かれたときの答えや許可で、会話で非常に多い。","style":"口語"},{"form":"ไม่ว่าจะ ＋ 形容詞 ＋ แค่ไหน","ro":"mâi wâa cà … khɛ̂ɛ nǎi","use":"「どんなに〜でも」。程度に関係なく結果が同じこと。","style":"標準"},{"form":"ไม่ว่าจะเป็น A หรือ B","ro":"mâi wâa cà pen … rʉ̌ʉ …","use":"「AでもBでも」。疑問詞の代わりに選択肢を並べる。案内文で多い。","style":"標準"},{"form":"ทุก ＋ 類別詞・名詞","ro":"thúk","use":"「すべての〜・毎〜」。ทุกคน「全員」、ทุกวัน「毎日」。事実を中立に述べる。","style":"標準"}],"cases":[{"th":"กินอะไรก็ได้","ro":"kin à rai kɔ̂ɔ dâai","ja":"（食べるのは）何でもいいよ。","note":"「何がいい？」と聞かれたときの典型的な答え。ไม่ว่า は使わない。"},{"th":"นั่งตรงไหนก็ได้","ro":"nâng trong nǎi kɔ̂ɔ dâai","ja":"どこに座ってもいいです。","note":"店員が客に言う言い方。ก็ได้ で「許可・どれでも可」。"},{"th":"ไม่ว่าจะยุ่งแค่ไหน เขาก็โทรหาแม่ทุกวัน","ro":"mâi wâa cà yûng khɛ̂ɛ nǎi khǎo kɔ̂ɔ thoo hǎa mɛ̂ɛ thúk wan","ja":"どんなに忙しくても、あの人は毎日母に電話する。","note":"ไม่ว่า＋แค่ไหน で「どんなに〜でも」。"},{"th":"ไม่ว่าจะเป็นเด็กหรือผู้ใหญ่ ก็เข้าได้ฟรี","ro":"mâi wâa cà pen dèk rʉ̌ʉ phûu yài kɔ̂ɔ khâo dâai frii","ja":"子どもでも大人でも、無料で入れます。","note":"疑問詞の代わりに「AかB」を置く形。"},{"th":"ไม่มีอะไรหรอก ไม่ต้องห่วง","ro":"mâi mii à rai rɔ̀ɔk mâi tɔ̂ɔng hùuang","ja":"何でもないよ、心配しないで。","note":"「何でもない」は ไม่มีอะไร。"}],"pitfalls":["「何でもいい」と「何でもない」を混同しない：อะไรก็ได้（どれでもいい）／ ไม่มีอะไร・ไม่เป็นไร（何でもない・大丈夫）。","ไม่ว่า の ว่า は「とがめる」の意味でも使う：ถ้าไม่ว่าอะไร ขอถามหน่อย「差し支えなければ、ちょっと聞いてもいい？」、ไม่ว่ากัน「責めないよ」。","「誰も・何も〜ない」は、まず ไม่มีใคร・ไม่…อะไรเลย の形を使う：ไม่มีใครรู้「誰も知らない」。ใครๆ ก็ไม่… は「誰だって〜ない」と強める言い方。"]},"44":{"lead":"การ・ความ は名詞を作る印ですが、日本語の「〜すること」「〜のこと」を毎回 การ にすると、会話では硬すぎる文になります。動詞のまま主語にする話し言葉、「〜さ」の ความ、「〜のこと」の เรื่อง を区別します。","compare":[{"form":"動詞句をそのまま主語に（กินผัก ＋ ดี…）","ro":"kin phàk dii …","use":"会話では การ を付けずに動詞句をそのまま主語にすることが多い。","style":"口語"},{"form":"ความ ＋ 形容詞（〜さ）","ro":"khwaam","use":"大きさや速さなど測れる性質。ความสูง「高さ」、ความเร็ว「速さ」。日本語の「〜さ」に近い。","style":"標準"},{"form":"เรื่อง ＋ 名詞・動詞","ro":"rʉ̂ʉang","use":"「〜のこと・〜の件」。話題を示す。เรื่องเงิน「お金のこと」。","style":"標準"}],"cases":[{"th":"กินผักเยอะๆ ดีต่อสุขภาพ","ro":"kin phàk yə́ yə́ dii tɔ̀ɔ sùk khà phâap","ja":"野菜をたくさん食べるのは健康にいい。","note":"会話では การ を付けない形が普通。文章なら การกินผัก…。"},{"th":"ตึกนี้มีความสูงสองร้อยเมตร","ro":"tʉ̀k níi mii khwaam sǔung sɔ̌ɔng rɔ́ɔi méet","ja":"このビルは高さ200メートルある。","note":"ความ＋形容詞で「〜さ」。会話では ตึกนี้สูงสองร้อยเมตร とも言う。"},{"th":"การบ้านเยอะมาก","ro":"kaan bâan yə́ mâak","ja":"宿題がとても多い。","note":"การบ้าน は一語の名詞。「家をすること」と分解して考えない。การเมือง「政治」も同じ。"},{"th":"เรื่องเงินไม่ต้องห่วง","ro":"rʉ̂ʉang ngəən mâi tɔ̂ɔng hùuang","ja":"お金のことは心配しないで。","note":"「〜のこと」は การ・ความ ではなく เรื่อง。"}],"pitfalls":["ชอบ・อยาก などの後ろには動詞をそのまま置く：ชอบว่ายน้ำ「泳ぐのが好き」。ชอบการว่ายน้ำ は文法的には言えるが、会話では硬く聞こえる。","「〜する人」は การ ではなく คน・นัก・ผู้ を使う：คนขับรถ「運転手」、นักเรียน「生徒」、ผู้ขาย「売り手」。","ความ の後ろに否定を入れて名詞にすることもある：ความไม่แน่นอน「不確かさ」。文章でよく見る形。"]},"45":{"lead":"日本語の「〜てしまう」は「完了」と「うっかり・残念」の両方を表しますが、タイ語では一語では済みません。全部使い切るのは หมด、うっかりは เผลอ、促しは ซะ と分かれ、「〜っぱなし」の ทิ้งไว้ も ไว้ と区別します。","compare":[{"form":"動詞 ＋ ทิ้งไว้","ro":"thíng wái","use":"「〜っぱなしにする・放っておく」。ไว้ だけなら「後のために〜ておく」。","style":"標準"},{"form":"動詞 ＋ หมด","ro":"mòt","use":"「全部〜してしまう・使い切る」。完了と量の「全部」を表す。","style":"標準"},{"form":"เผลอ ＋ 動詞","ro":"phlə̌ə","use":"「うっかり・思わず〜してしまう」。意図しない動作。動詞の前に置く。","style":"標準"},{"form":"動詞 ＋ ซะ","ro":"sá","use":"「さっさと〜してしまいなさい」と促す。เสีย の会話形で、命令調になりやすいので นะ を添えることが多い。","style":"口語"}],"cases":[{"th":"เผลอหลับไป","ro":"phlə̌ə làp pai","ja":"うっかり寝てしまった。","note":"「うっかり」は เผลอ。後ろの ไป は意識が離れていく変化。"},{"th":"กินหมดแล้ว","ro":"kin mòt lɛ́ɛo","ja":"全部食べてしまった。","note":"量を使い切った「〜てしまう」は หมด。กินไปแล้ว は「もう食べた」に近く、全部とは限らない。"},{"th":"เปิดไฟทิ้งไว้","ro":"pə̀ət fai thíng wái","ja":"電気をつけっぱなしにしてある。","note":"ทิ้งไว้ は放置の「〜っぱなし」。うっかりなら เผลอ を加える。"},{"th":"กินข้าวซะ แล้วค่อยเล่น","ro":"kin khâao sá lɛ́ɛo khɔ̂ɔi lên","ja":"ご飯を食べてしまいなさい。遊ぶのはそれから。","note":"親が子に言うような促しの ซะ。"}],"pitfalls":["「〜てしまった（残念）」を全部 ไป にしない。ไป は失われる・離れる動作が中心で、ทำแก้วแตก「コップを割ってしまった」のように何も付けないことも多い。","形容詞＋ไป は「〜すぎる」：เผ็ดไป「辛すぎる」。เกินไป を使うとさらにはっきりする：เผ็ดเกินไป。","目的語は動詞と ไว้ の間に置くのが基本：จองโต๊ะไว้（○）。จองไว้โต๊ะ は不自然。"]},"46":{"lead":"日本語の「〜てください」は場面を問わず使えますが、店員や友人に กรุณา を使うと、掲示を読み上げたような距離のある響きになります。会話の ช่วย…หน่อย に加え、รบกวน、เชิญ、物を頼む ขอ を使い分けます。","compare":[{"form":"รบกวน（ช่วย）＋ 動詞","ro":"róp kuuan","use":"「お手数ですが〜」。手間をかける相手への丁寧な依頼。職場の会話やメール・チャットで多い。","style":"丁寧"},{"form":"เชิญ ＋ 動詞","ro":"chəən","use":"「どうぞ〜してください」。相手のためになる動作をすすめる。","style":"丁寧"},{"form":"ขอ ＋ 物（＋ หน่อย）","ro":"khɔ̌ɔ … nɔ̀ɔi","use":"「〜をください」。物を頼むときは動詞を使わず ขอ。","style":"標準"},{"form":"กรุณา ／ โปรด ＋ 動詞","ro":"kà rú naa ／ pròot","use":"どちらも掲示・案内向き。โปรด のほうがさらに硬く、案内放送や公式文書で多い。","style":"改まった表現"}],"cases":[{"th":"ช่วยปิดประตูหน่อยครับ","ro":"chûuai pìt prà tuu nɔ̀ɔi khráp","ja":"ドアを閉めてもらえますか。","note":"日常の依頼はこの形。กรุณาปิดประตู は貼り紙の文言。"},{"th":"รบกวนส่งเอกสารภายในวันนี้ด้วยนะครับ","ro":"róp kuuan sòng èek kà sǎan phaai nai wan níi dûuai ná khráp","ja":"お手数ですが、今日中に書類を送ってください。","note":"仕事のやり取りで多い丁寧な依頼。文末の ด้วยนะครับ も依頼でよく使う。"},{"th":"เชิญนั่งครับ","ro":"chəən nâng khráp","ja":"どうぞお座りください。","note":"相手の得になる動作なので เชิญ。ช่วยนั่ง とは言わない。"},{"th":"โปรดปิดเสียงโทรศัพท์มือถือ","ro":"pròot pìt sǐiang thoo rá sàp mʉʉ thʉ̌ʉ","ja":"携帯電話の音をお切りください。","note":"映画館や会場の案内。会話では使わない硬さ。"},{"th":"ขอน้ำแข็งหน่อยครับ","ro":"khɔ̌ɔ nám khɛ̌ng nɔ̀ɔi khráp","ja":"氷をください。","note":"物を頼む「〜をください」は ขอ＋物。กรุณา は付けない。"}],"pitfalls":["「〜てください」を全部 กรุณา にしない。屋台・タクシー・友人には ช่วย…หน่อย や 動詞＋หน่อย・ด้วย が自然。","เชิญ は相手のための「どうぞ」専用。自分のための依頼に เชิญ は使えない：เชิญช่วยผม（×）→ ช่วยผมหน่อย（○）。","รบกวน は本来「邪魔する」。ขอโทษที่รบกวน は「お邪魔してすみません」で、依頼ではなくおわびの言い方。"]},"47":{"lead":"ไม่เพียงแต่…แต่ยัง… は文章向きで、会話では ทั้ง…ทั้ง…・แถม などもよく使います。後半が名詞のときの形や、否定と組んだ「AもBも〜ない」も押さえます。","compare":[{"form":"ทั้ง ＋ A ＋ ทั้ง ＋ B","ro":"tháng … tháng …","use":"「AでもありBでもある」。形容詞や動詞を並べる会話的な形。","style":"口語"},{"form":"A ＋ แถม ＋ B","ro":"thɛ̌ɛm","use":"「その上・おまけに」。良いことにも悪いことにも使い、文句を重ねるときにも多い。","style":"口語"},{"form":"（主語）＋ ก็ ＋ 動詞 ＋ ด้วย","ro":"kɔ̂ɔ … dûuai","use":"単純な「〜も」。ไม่เพียงแต่ を使うほどではない付け加え。","style":"標準"}],"cases":[{"th":"เธอทั้งสวยทั้งเก่ง","ro":"thəə tháng sǔuai tháng kèng","ja":"彼女はきれいで、しかも有能だ。","note":"ほめ言葉の典型的な形。ทั้ง を二回使う。"},{"th":"ร้านนี้แพง แถมไม่อร่อยด้วย","ro":"ráan níi phɛɛng thɛ̌ɛm mâi à rɔ̀ɔi dûuai","ja":"この店は高いし、おまけにおいしくない。","note":"悪い点を重ねる แถม。文末の ด้วย と組むことが多い。"},{"th":"เขาไม่ใช่แค่เพื่อน แต่เป็นเหมือนพี่ชาย","ro":"khǎo mâi châi khɛ̂ɛ phʉ̂ʉan tɛ̀ɛ pen mʉ̌ʉan phîi chaai","ja":"あの人はただの友達ではなく、兄のような存在だ。","note":"後半が名詞なら เป็น を入れて แต่เป็น・แต่ยังเป็น にする。"},{"th":"ผมไม่กินทั้งหมูและเนื้อ","ro":"phǒm mâi kin tháng mǔu lɛ́ nʉ́ʉa","ja":"私は豚肉も牛肉も食べない。","note":"否定と組むと、ふつう「AもBも〜ない」と読む。"},{"th":"เขาไป ผมก็ไปด้วย","ro":"khǎo pai phǒm kɔ̂ɔ pai dûuai","ja":"あの人が行くなら、私も行く。","note":"単純な「〜も」は ก็…ด้วย。ไม่เพียงแต่ は大げさになる。"}],"pitfalls":["日本語の「も」は語のすぐ後ろだが、タイ語の ด้วย は文の終わりに置く：ผมไปด้วย（○）。ก็ は主語の後ろ・動詞の前に入る。","ทั้ง だけだと「〜じゅう・全部」の意味になる：ทั้งวัน「一日中」、ทั้งหมด「全部」。ทั้ง…และ… の ทั้ง と区別する。","แถม は動詞「おまけを付ける」でもある：แถมให้อีกหนึ่งชิ้น「もう一つおまけしてくれた」、ของแถม「おまけ」。"]}};
